-- P03 (keputusan owner 29 Okt): kunci "jual di bawah HPP" diperluas.
--
-- 1. Kasir petshop (cashier_post_stock_atomic): baris paket "Grup" yang berisi komponen
--    Persediaan tidak lagi dilewati. Harga netonya wajib > 0 dan >= jumlah HPP FIFO aktual
--    komponennya (yang sudah dijumlahkan ke sale_items.hpp oleh fungsi yang sama). Pesan
--    penolakan kini menyebut nama barisnya. Paket berisi jasa saja tetap boleh gratis.
-- 2. Kasir klinik (clinic_post_invoice, termasuk jalur split dan DEMO yang memanggilnya,
--    serta koreksi clinic_edit_invoice_core): obat/barang (baris jenis 'obat' bertaut barang
--    atau racikan) ditolak bila harga neto nol atau di bawah HPP aktual baris itu. Komponen
--    paket (package_item_id) dinilai per paket: neto seluruh baris paket vs jumlah HPP
--    komponennya. Jasa/tindakan tetap boleh gratis. Diskon invoice dibagi proporsional.
--    Pemeriksaan berjalan di transaksi yang sama sesudah stok dikeluarkan dan sebelum
--    jurnal, jadi penolakan membatalkan stok, HPP, dan invoice sekaligus.
--
-- Fungsi yang ditambal memakai pola anchored replace: gagal keras bila definisinya sudah
-- berubah dari teks yang ditinjau. Signature, SECURITY DEFINER, search_path dan grant tetap.

-- ---------------------------------------------------------------------------
-- 1. Kasir petshop: Grup ikut dinilai.
-- ---------------------------------------------------------------------------
do $p03_cashier$
declare
  signature regprocedure := 'public.cashier_post_stock_atomic(uuid,uuid)'::regprocedure;
  definition text := pg_get_functiondef(signature);
  old_text text := $old$ for line in select i.*, m.item_type from public.sale_items i
  left join public.items m on m.id=i.item_id where i.sale_id=s.id and m.item_type='Persediaan' order by i.id loop
  gross := line.qty * line.harga;
  manual := case when line.item_discount_type = 'percent' then round(gross * coalesce(line.item_discount_value,0) / 100,0)
   else coalesce(line.item_discount_value,0) end;
  item_discount := least(greatest(case when manual > 0 then manual else coalesce(line.promo_discount,0) end,0),gross);
  if after_items <= 0 or (gross-item_discount)*net_total/after_items <= 0 then
   raise exception 'Harga neto Persediaan nol; penjualan ditolak' using errcode='55000';
  end if;
  if line.hpp is null or (gross-item_discount)*net_total/after_items < line.hpp then
   raise exception 'Harga neto Persediaan di bawah HPP FIFO; penjualan ditolak' using errcode='55000';
  end if;
 end loop;$old$;
  new_text text := $new$ -- P03_GRUP_FLOOR: a package line with stock components is goods; its hpp
 -- already holds the summed actual FIFO cost of those components.
 for line in select i.*, m.item_type from public.sale_items i
  left join public.items m on m.id=i.item_id where i.sale_id=s.id and (m.item_type='Persediaan'
   or (m.item_type='Grup' and exists(select 1 from public.sale_item_group_components gc
    where gc.sale_item_id=i.id and gc.item_type='Persediaan'))) order by i.id loop
  gross := line.qty * line.harga;
  manual := case when line.item_discount_type = 'percent' then round(gross * coalesce(line.item_discount_value,0) / 100,0)
   else coalesce(line.item_discount_value,0) end;
  item_discount := least(greatest(case when manual > 0 then manual else coalesce(line.promo_discount,0) end,0),gross);
  if after_items <= 0 or (gross-item_discount)*net_total/after_items <= 0 then
   if line.item_type = 'Grup' then
    raise exception 'Harga neto paket Grup nol; penjualan ditolak: %', line.nama using errcode='55000';
   end if;
   raise exception 'Harga neto Persediaan nol; penjualan ditolak: %', line.nama using errcode='55000';
  end if;
  if line.hpp is null or (gross-item_discount)*net_total/after_items < line.hpp then
   if line.item_type = 'Grup' then
    raise exception 'Harga neto paket Grup di bawah total HPP FIFO komponen; penjualan ditolak: %', line.nama using errcode='55000';
   end if;
   raise exception 'Harga neto Persediaan di bawah HPP FIFO; penjualan ditolak: %', line.nama using errcode='55000';
  end if;
 end loop;$new$;
begin
  if position('P03_GRUP_FLOOR' in definition) > 0 then
    raise exception 'P03 cashier floor already applied; inspect before re-running';
  end if;
  if (length(definition) - length(replace(definition, old_text, ''))) / length(old_text) <> 1 then
    raise exception 'P03_DRIFT: cashier_post_stock_atomic changed; review before release';
  end if;
  execute replace(definition, old_text, new_text);
end $p03_cashier$;
revoke all on function public.cashier_post_stock_atomic(uuid,uuid) from public,anon,service_role;
grant execute on function public.cashier_post_stock_atomic(uuid,uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 2. Kasir klinik: satu pemeriksa, dipanggil dari posting dan koreksi.
-- ---------------------------------------------------------------------------
create function clinic_private.rupiah_text(p_value numeric) returns text
language sql immutable set search_path = '' as $$
  select 'Rp' || replace(to_char(round(coalesce(p_value, 0)), 'FM999,999,999,999,990'), ',', '.')
$$;
revoke all on function clinic_private.rupiah_text(numeric) from public, anon, authenticated, service_role;

create function clinic_private.assert_invoice_price_floor(p_invoice_id uuid, p_subtotal numeric, p_discount numeric)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_share numeric;
  v_line record;
  v_net numeric;
begin
  if p_subtotal is null or p_discount is null or p_subtotal < 0 or p_discount < 0 or p_discount > p_subtotal then
    raise exception using errcode = 'P0001', message = 'INVOICE_INVALID: nilai invoice tidak konsisten';
  end if;
  -- Invoice-level discount is apportioned by each line's share of the subtotal, the
  -- same convention as the petshop cashier. Tax is not revenue and is ignored.
  v_share := case when p_subtotal > 0 then (p_subtotal - p_discount) / p_subtotal else 0 end;

  -- Standalone goods: medicine/stock lines linked to a master item, and compounded
  -- medicine (racikan). Services (jenis 'jasa'), including procedures that consume
  -- BMHP, stay free to price at zero.
  for v_line in
    select ii.deskripsi, ii.hpp,
      round(ii.qty * ii.harga * (1 - coalesce(ii.diskon_persen, 0) / 100), 2) as amount
    from public.invoice_items ii
    where ii.invoice_id = p_invoice_id and ii.package_item_id is null and ii.jenis = 'obat'
      and (ii.item_id is not null or ii.compound_recipe_id is not null)
    order by ii.deskripsi, ii.id
  loop
    v_net := round(v_line.amount * v_share, 2);
    if v_net <= 0 then
      raise exception using errcode = 'P0001', message = format(
        'PRICE_ZERO: Harga neto %s Rp0. Obat/barang tidak boleh dijual gratis (jasa tetap boleh gratis).',
        v_line.deskripsi);
    end if;
    if v_line.hpp is null then
      raise exception using errcode = 'P0001', message = format('COST_MISSING: %s', v_line.deskripsi);
    end if;
    if v_net < v_line.hpp then
      raise exception using errcode = 'P0001', message = format(
        'PRICE_BELOW_HPP: Harga neto %s %s di bawah HPP %s. Naikkan harga atau kurangi diskon.',
        v_line.deskripsi, clinic_private.rupiah_text(v_net), clinic_private.rupiah_text(v_line.hpp));
    end if;
  end loop;

  -- Package components are judged per package: the net of every line tagged with the
  -- package against the summed HPP of its components. A package of services only stays free.
  for v_line in
    select ii.package_item_id, coalesce(max(i.name), 'paket') as package_name,
      sum(round(ii.qty * ii.harga * (1 - coalesce(ii.diskon_persen, 0) / 100), 2)) as amount,
      sum(coalesce(ii.hpp, 0)) as hpp
    from public.invoice_items ii
    left join public.items i on i.id = ii.package_item_id
    where ii.invoice_id = p_invoice_id and ii.package_item_id is not null
    group by ii.package_item_id
    having bool_or(ii.jenis = 'obat' and (ii.item_id is not null or ii.compound_recipe_id is not null))
    order by 2, 1
  loop
    v_net := round(v_line.amount * v_share, 2);
    if v_net <= 0 then
      raise exception using errcode = 'P0001', message = format(
        'PRICE_ZERO: Harga neto paket %s Rp0. Paket yang berisi obat/barang tidak boleh gratis.',
        v_line.package_name);
    end if;
    if v_net < v_line.hpp then
      raise exception using errcode = 'P0001', message = format(
        'PRICE_BELOW_HPP: Harga neto paket %s %s di bawah total HPP komponennya %s. Naikkan harga atau kurangi diskon.',
        v_line.package_name, clinic_private.rupiah_text(v_net), clinic_private.rupiah_text(v_line.hpp));
    end if;
  end loop;
end $$;
revoke all on function clinic_private.assert_invoice_price_floor(uuid, numeric, numeric)
  from public, anon, authenticated, service_role;

do $p03_clinic$
declare
  p record;
  definition text;
begin
  for p in select * from (values
    ('public.clinic_post_invoice(uuid,text,jsonb,jsonb)',
     E'  select round(coalesce(sum(ii.hpp), 0), 2)::numeric(15,2)\n    into v_total_hpp from public.invoice_items ii where ii.invoice_id = v_invoice_id;\n',
     E'  select round(coalesce(sum(ii.hpp), 0), 2)::numeric(15,2)\n    into v_total_hpp from public.invoice_items ii where ii.invoice_id = v_invoice_id;\n'
     || E'  -- P03_PRICE_FLOOR: goods below actual HPP roll back the whole posting.\n'
     || E'  perform clinic_private.assert_invoice_price_floor(v_invoice_id, v_subtotal, v_discount);\n'),
    ('public.clinic_edit_invoice_core(uuid,text,jsonb,jsonb)',
     E'  select coalesce(sum(hpp),0) into v_total_hpp from public.invoice_items where invoice_id=p_invoice_id;\n',
     E'  select coalesce(sum(hpp),0) into v_total_hpp from public.invoice_items where invoice_id=p_invoice_id;\n'
     || E'  -- P03_PRICE_FLOOR: a correction cannot move goods below actual HPP either.\n'
     || E'  perform clinic_private.assert_invoice_price_floor(p_invoice_id, v_subtotal, v_discount);\n')
  ) as patches(sig, old_text, new_text) loop
    definition := pg_get_functiondef(p.sig::regprocedure);
    if position('P03_PRICE_FLOOR' in definition) > 0 then
      raise exception 'P03 clinic floor already applied to %; inspect before re-running', p.sig;
    end if;
    if (length(definition) - length(replace(definition, p.old_text, ''))) / length(p.old_text) <> 1 then
      raise exception 'P03_DRIFT: % changed; review before release', p.sig;
    end if;
    execute replace(definition, p.old_text, p.new_text);
  end loop;
end $p03_clinic$;
revoke all on function public.clinic_post_invoice(uuid,text,jsonb,jsonb) from public, anon, service_role;
grant execute on function public.clinic_post_invoice(uuid,text,jsonb,jsonb) to authenticated;

-- J02 lanjutan (keputusan Owner 29 Okt): koreksi Tunai<->Transfer pada penjualan POS
-- boleh dilakukan OWNER dan FINANCE, termasuk sesudah shift kasir ditutup.
--
-- * Shift yang sudah ditutup TIDAK dibuka ulang dan angka penutupannya
--   (expected_cash, closing_breakdown, selisih) tidak diubah. Barisnya hanya dikunci
--   FOR UPDATE agar koreksi tidak berlomba dengan proses tutup shift, lalu statusnya
--   dicatat di jejak koreksi (source_shift_status).
-- * Jurnal pembalik + pengganti tetap bertanggal hari koreksi (WIB). Aturan periode
--   tidak berubah: ditolak bila tanggal sumber ATAU tanggal koreksi berada di periode
--   yang sudah ditutup (check_period_lock memblokir jurnal bertanggal <= closed_until).
-- * Penolakan lain (kembalian tunai, fee Tunai/Transfer, sumber legacy, retur/refund,
--   rekonsiliasi bank, revisi basi, peta akun berubah) tetap berlaku.
--
-- Fungsi diganti dengan patch berjangkar: signature, SECURITY DEFINER, search_path,
-- lock_timeout dan grant tetap. Jangkar yang tidak ditemukan tepat satu kali
-- menggagalkan migrasi.
alter table public.sale_payment_corrections add column if not exists source_shift_status text;

do $patch$
declare
 signature regprocedure:='public.correct_pos_sale_payment(uuid,integer,text,text,numeric,numeric)'::regprocedure;
 body text;
 anchors text[]:=array[
  -- 1. variabel status shift
  $a$ audit uuid:=gen_random_uuid();$a$,
  -- 2. peran OWNER saja + modul penjualan -> OWNER/FINANCE + akses cabang
  $a$ perform 1 from public.profiles where id=actor and is_active and role='OWNER' for share;
 if not found then raise exception 'Hanya Owner aktif dapat mengoreksi metode pembayaran' using errcode='42501';end if;
 perform public.sales_assert_access(s.branch_id);$a$,
  -- 3. shift wajib open -> shift dikunci, status dicatat
  $a$ if s.shift_id is not null then
  perform 1 from public.cashier_shifts where id=s.shift_id and branch_id=s.branch_id and status='open' for update;
  if not found then raise exception 'Shift kasir sudah ditutup; rekonsiliasi shift diperlukan';end if;
 end if;$a$,
  -- 4. jejak koreksi menyimpan status shift sumber
  $a$original_journal_id,reversal_journal_id,replacement_journal_id,created_by)
  values(audit,s.id,s.branch_id,s.revision+1,btrim(p_reason),to_jsonb(s),before_payments,after_payments,
   source_journal.id,reversal,replacement,actor);$a$,
  -- 5. hasil RPC menyebut status shift sumber
  $a$'reversal_journal_id',reversal,'replacement_journal_id',replacement);$a$
 ];
 replacements text[]:=array[
  $r$ audit uuid:=gen_random_uuid();shift_status text;$r$,
  $r$ perform 1 from public.profiles where id=actor and is_active and role in('OWNER','FINANCE') for share;
 if not found then raise exception 'Hanya Owner atau Finance aktif dapat mengoreksi metode pembayaran' using errcode='42501';end if;
 if not public.user_can_access_branch(s.branch_id) then
  raise exception 'Dokumen penjualan tidak ditemukan atau tidak dapat diakses.' using errcode='42501';end if;$r$,
  $r$ -- J02_AFTER_SHIFT: shift ditutup tidak dibuka ulang; angka penutupannya tidak disentuh.
 if s.shift_id is not null then
  select status into shift_status from public.cashier_shifts where id=s.shift_id and branch_id=s.branch_id for update;
  if not found then raise exception 'Shift kasir sumber tidak ditemukan; rekonsiliasi shift diperlukan';end if;
 end if;$r$,
  $r$original_journal_id,reversal_journal_id,replacement_journal_id,created_by,source_shift_status)
  values(audit,s.id,s.branch_id,s.revision+1,btrim(p_reason),to_jsonb(s),before_payments,after_payments,
   source_journal.id,reversal,replacement,actor,shift_status);$r$,
  $r$'reversal_journal_id',reversal,'replacement_journal_id',replacement,'source_shift_status',shift_status);$r$
 ];
 i integer;
begin
 body:=pg_get_functiondef(signature);
 if position('J02_AFTER_SHIFT' in body)>0 then
  raise exception 'J02_AFTER_SHIFT patch already present; verify migration history';end if;
 for i in 1..array_length(anchors,1) loop
  if (length(body)-length(replace(body,anchors[i],'')))/length(anchors[i])<>1 then
   raise exception 'J02_AFTER_SHIFT anchor % not found exactly once; review correct_pos_sale_payment',i;end if;
  body:=replace(body,anchors[i],replacements[i]);
 end loop;
 execute body;
end $patch$;

-- Grant tidak berubah oleh CREATE OR REPLACE; ditegaskan ulang agar kontraknya terlihat.
revoke all on function public.correct_pos_sale_payment(uuid,integer,text,text,numeric,numeric)
 from public,anon,authenticated,service_role;
grant execute on function public.correct_pos_sale_payment(uuid,integer,text,text,numeric,numeric) to authenticated;

-- Jejak koreksi dibaca OWNER dan FINANCE pada cabang yang boleh diakses.
drop policy if exists sale_payment_corrections_owner_read on public.sale_payment_corrections;
create policy sale_payment_corrections_finance_read on public.sale_payment_corrections for select to authenticated using (
 exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_active and p.role in('OWNER','FINANCE'))
 and public.user_can_access_branch(branch_id)
);

-- J02 lanjutan (keputusan Owner 29 Okt): koreksi metode pembayaran invoice klinik
-- Tunai <-> Transfer oleh OWNER atau FINANCE, juga sesudah shift kasir ditutup.
--
-- Yang dikoreksi satu "bagian pembayaran" utuh:
--  * baris invoice_payments (bagian split saat checkout / pelunasan piutang), atau
--  * pembayaran langsung invoice (lunas sekali bayar, atau uang muka/DP) yang
--    tercatat di jurnal pendapatan 'klinik' (p_payment_id = null).
-- Nominal tidak berubah, tidak ada baris pembayaran / struk baru, baris split tetap
-- menempel pada invoice & checkout yang sama (id, invoice_id, checkout_payment,
-- request_key, request_hash tidak diubah supaya retry pelunasan lama tetap idempoten).
--
-- Akuntansi: satu jurnal koreksi bertanggal hari koreksi (WIB), source
-- 'klinik-koreksi-bayar', source_ref = nomor invoice:
--   Dr rekening metode baru (peta payment_account_map cabang, lalu global)
--   Cr rekening asal yang benar-benar didebit jurnal sumber.
-- Jurnal pendapatan/pelunasan asal tidak diubah. Shift kasir tidak dibuka ulang;
-- angka penutupan shift tidak disentuh (status shift dicatat di jejak koreksi).
-- Ditolak bila: tanggal sumber atau tanggal koreksi di periode tertutup, rekonsiliasi
-- bank mencakup rekening asal/tujuan sejak tanggal sumber, revisi basi, invoice
-- void/terbit ulang/pending koreksi, ada refund/permintaan refund aktif, bagian
-- pindahan (transferred_from), metode bukan Tunai/Transfer, peta akun belum lengkap,
-- atau saldo kas/bank invoice di buku besar tidak cocok dengan pembayaran tercatat.

create table public.clinic_payment_corrections (
 id uuid primary key default gen_random_uuid(),
 invoice_id uuid not null references public.invoices(id) on delete restrict,
 invoice_payment_id uuid references public.invoice_payments(id) on delete restrict,
 branch_id uuid not null references public.branches(id) on delete restrict,
 revision integer not null check(revision>0),
 amount numeric(15,2) not null check(amount>0),
 from_method text not null check(from_method in('Tunai','Transfer')),
 to_method text not null check(to_method in('Tunai','Transfer')),
 from_code text not null,
 to_code text not null,
 reason text not null,
 source_shift_id uuid,
 source_shift_status text,
 before_snapshot jsonb not null,
 after_snapshot jsonb not null,
 journal_id uuid not null unique references public.journal_entries(id) on delete restrict,
 created_by uuid not null references public.profiles(id) on delete restrict,
 created_at timestamptz not null default clock_timestamp(),
 unique(invoice_id,revision),
 check(from_method<>to_method and from_code<>to_code)
);
create index clinic_payment_corrections_invoice_idx on public.clinic_payment_corrections(invoice_id,revision desc);
alter table public.clinic_payment_corrections enable row level security;
revoke all on public.clinic_payment_corrections from public,anon,authenticated,service_role;
grant select on public.clinic_payment_corrections to authenticated;
create policy clinic_payment_corrections_finance_read on public.clinic_payment_corrections for select to authenticated using (
 exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_active and p.role in('OWNER','FINANCE'))
 and public.user_can_access_branch(branch_id)
);

create table public.clinic_payment_correction_requests (
 actor_id uuid not null references public.profiles(id) on delete restrict,
 request_key text not null,
 invoice_id uuid not null references public.invoices(id) on delete restrict,
 payload jsonb not null,
 result jsonb not null,
 created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,request_key)
);
alter table public.clinic_payment_correction_requests enable row level security;
revoke all on public.clinic_payment_correction_requests from public,anon,authenticated,service_role;

-- Void/terbit ulang/edit invoice membaca rekening kas dari jurnal sumber 'klinik'.
-- Setelah koreksi, jalur itu akan memindahkan kas ke rekening lama. Fail closed
-- sampai jalur pembatalan merekonsiliasi rantai koreksi (pola sama dengan POS).
create function public.guard_clinic_payment_corrected_invoice() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.clinic_payment_corrections where invoice_id=old.id) and (
  new.voided_at is distinct from old.voided_at or new.visit_id is distinct from old.visit_id
  or new.invoice_no is distinct from old.invoice_no or new.subtotal is distinct from old.subtotal
  or new.discount is distinct from old.discount or new.tax is distinct from old.tax
  or new.total is distinct from old.total or new.dp_amount is distinct from old.dp_amount
  or new.reissued_from is distinct from old.reissued_from
  or new.correction_pending is distinct from old.correction_pending) then
  raise exception using errcode='P0001',
   message='PAYMENT_CORRECTED: invoice dengan koreksi metode pembayaran perlu rekonsiliasi sebelum dikoreksi atau dibatalkan';
 end if;
 return new;
end $$;
revoke all on function public.guard_clinic_payment_corrected_invoice() from public,anon,authenticated,service_role;
create trigger clinic_payment_corrected_invoice_guard before update on public.invoices for each row
 execute function public.guard_clinic_payment_corrected_invoice();

create function public.correct_clinic_invoice_payment(
 p_invoice_id uuid,p_payment_id uuid,p_expected_revision integer,p_request_key text,p_reason text,p_new_method text
) returns jsonb
language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
declare
 actor uuid:=auth.uid();vis public.visits%rowtype;inv public.invoices%rowtype;pay public.invoice_payments%rowtype;
 prior public.clinic_payment_correction_requests%rowtype;last_direct public.clinic_payment_corrections%rowtype;
 to_account public.cash_accounts%rowtype;
 payload jsonb;result jsonb;before_snapshot jsonb;after_snapshot jsonb;
 current_revision integer;amount numeric;old_method text;from_code text;to_code text;
 direct numeric:=0;direct_code text;direct_debit numeric;line_count integer;journal_count integer;
 source_date date;closed date;today date:=(now() at time zone 'Asia/Jakarta')::date;
 shift_status text;ledger numeric;expected numeric;journal uuid;audit uuid:=gen_random_uuid();
begin
 if actor is null or auth.role() is distinct from 'authenticated' then raise exception 'Sesi login diperlukan' using errcode='42501';end if;
 if p_invoice_id is null or p_expected_revision is null or p_expected_revision<0
  or length(btrim(coalesce(p_request_key,''))) not between 1 and 120
  or length(btrim(coalesce(p_reason,''))) not between 3 and 1000
  or p_new_method is null or p_new_method not in('Tunai','Transfer') then
  raise exception 'Identitas, alasan atau metode koreksi tidak valid' using errcode='22023';end if;

 -- Visit lalu invoice: urutan kunci sama dengan posting, pelunasan dan void/reissue.
 select v.* into vis from public.visits v join public.invoices x on x.visit_id=v.id where x.id=p_invoice_id;
 if not found then raise exception 'Invoice tidak ditemukan' using errcode='42501';end if;
 perform 1 from public.visits where id=vis.id for update;
 select * into inv from public.invoices where id=p_invoice_id for update;
 perform 1 from public.profiles where id=actor and is_active and role in('OWNER','FINANCE') for share;
 if not found then raise exception 'Hanya Owner atau Finance aktif dapat mengoreksi metode pembayaran' using errcode='42501';end if;
 if not public.user_can_access_branch(vis.branch_id) then raise exception 'Invoice tidak ditemukan atau tidak dapat diakses' using errcode='42501';end if;
 perform 1 from public.branches where id=vis.branch_id and is_active for share;
 if not found then raise exception 'Cabang sumber tidak aktif' using errcode='42501';end if;

 payload:=jsonb_build_object('invoice_id',p_invoice_id,'payment_id',p_payment_id,'revision',p_expected_revision,
  'reason',btrim(p_reason),'method',p_new_method);
 perform pg_advisory_xact_lock(hashtextextended('vetos:clinic-payment-correction:'||actor::text||':'||p_request_key,0));
 select * into prior from public.clinic_payment_correction_requests where actor_id=actor and request_key=p_request_key;
 if found then
  if prior.payload is distinct from payload then raise exception 'Identitas simpan sudah dipakai untuk rincian berbeda';end if;
  return prior.result;
 end if;

 select count(*) into current_revision from public.clinic_payment_corrections where invoice_id=inv.id;
 if current_revision<>p_expected_revision then raise exception 'Invoice sudah berubah. Muat ulang sebelum koreksi';end if;
 if inv.voided_at is not null or inv.request_key is null or inv.invoice_no is null or inv.correction_pending then
  raise exception 'Invoice belum memenuhi syarat koreksi metode; invoice batal, terbit ulang tertunda atau sumber legacy memerlukan rekonsiliasi';end if;
 if exists(select 1 from public.clinic_refunds where invoice_id=inv.id)
  or exists(select 1 from public.clinic_refund_requests where invoice_id=inv.id and status in('pending','diproses')) then
  raise exception 'Invoice sudah memiliki refund atau permintaan refund; rekonsiliasi sumber diperlukan';end if;

 -- Pembayaran langsung (lunas sekali bayar / DP) tercatat di jurnal 'klinik'.
 if inv.reissued_from is null then
  direct:=case when inv.paid_status='Lunas' and not exists(select 1 from public.invoice_payments where invoice_id=inv.id)
   then inv.total else coalesce(inv.dp_amount,0) end;
 end if;
 select count(*) into journal_count from public.journal_entries
  where source='klinik' and source_ref=inv.invoice_no and voided_at is null;
 if direct>0 then
  if journal_count<>1 then raise exception 'Jurnal pendapatan invoice tidak tunggal; rekonsiliasi diperlukan';end if;
  select * into last_direct from public.clinic_payment_corrections
   where invoice_id=inv.id and invoice_payment_id is null order by revision desc limit 1;
  if found then direct_code:=last_direct.to_code;
  else
   select count(*),min(a.code),min(l.debit) into line_count,direct_code,direct_debit
    from public.journal_entries e join public.journal_lines l on l.entry_id=e.id
    join public.coa_accounts a on a.id=l.account_id
    where e.source='klinik' and e.source_ref=inv.invoice_no and e.voided_at is null
     and l.debit>0 and a.code not in('1201','4102');
   if line_count<>1 or direct_debit is distinct from direct then
    raise exception 'Rekening pembayaran awal invoice tidak ditemukan atau tidak tunggal';end if;
  end if;
 end if;

 if p_payment_id is null then
  if direct<=0 then raise exception 'Invoice ini tidak memiliki pembayaran langsung; pilih bagian pembayarannya';end if;
  amount:=direct;old_method:=inv.metode_bayar;from_code:=direct_code;
  select tanggal into source_date from public.journal_entries
   where source='klinik' and source_ref=inv.invoice_no and voided_at is null;
 else
  select * into pay from public.invoice_payments where id=p_payment_id and invoice_id=inv.id for update;
  if not found then raise exception 'Bagian pembayaran tidak ditemukan pada invoice ini';end if;
  if pay.transferred_from is not null or pay.kas_code is null or pay.amount is null or pay.amount<=0 then
   raise exception 'Bagian pembayaran pindahan atau tanpa rekening memerlukan rekonsiliasi';end if;
  amount:=pay.amount;old_method:=pay.metode;from_code:=pay.kas_code;source_date:=pay.tanggal;
 end if;
 if old_method is null or old_method not in('Tunai','Transfer') then
  raise exception 'Hanya pembayaran Tunai atau Transfer yang dapat dikoreksi';end if;
 if old_method=p_new_method then raise exception 'Koreksi tidak mengubah metode pembayaran';end if;
 if amount<>round(amount,2) then raise exception 'Nominal sumber tidak valid';end if;

 select closed_until into closed from public.accounting_locks where id for share;
 if source_date is null or source_date>today or (closed is not null and (source_date<=closed or today<=closed)) then
  raise exception 'Periode sumber atau koreksi telah ditutup atau tanggal sumber tidak valid';end if;

 -- Shift sumber hanya dikunci (serialisasi dengan tutup shift) dan dicatat; tidak dibuka ulang.
 if inv.shift_id is not null then
  select status into shift_status from public.cashier_shifts where id=inv.shift_id for update;
 end if;

 select ca.* into to_account from public.payment_account_map m join public.cash_accounts ca on ca.id=m.cash_account_id
  where m.metode=p_new_method and (m.branch_id=vis.branch_id or m.branch_id is null)
  order by m.branch_id nulls last limit 1;
 if not found or not to_account.is_active or (to_account.branch_id is not null and to_account.branch_id<>vis.branch_id) then
  raise exception 'Rekening % belum dipetakan atau tidak aktif untuk cabang ini',p_new_method;end if;
 to_code:=to_account.coa_code;
 if to_code is null or to_code=from_code then raise exception 'Rekening asal dan tujuan sama; periksa peta akun Tunai dan Transfer';end if;
 perform 1 from public.coa_accounts where code in(from_code,to_code) and is_active and not is_header
  and type='ASET' and normal_balance='D' for share;
 if (select count(*) from public.coa_accounts where code in(from_code,to_code) and is_active and not is_header
  and type='ASET' and normal_balance='D')<>2 then raise exception 'Akun asal/tujuan bukan aset detail aktif';end if;

 -- Serialisasi snapshot buku besar dengan rekonsiliasi bank dan koreksi lain.
 lock table public.journal_entries,public.journal_lines in share row exclusive mode;
 if exists(select 1 from public.bank_reconciliations r left join public.cash_accounts a on a.id=r.cash_account_id
  left join public.coa_accounts c on c.code=coalesce(r.bank_coa_code,a.coa_code)
  where r.voided_at is null and r.tanggal>=source_date
   and (c.id is null or c.code in(from_code,to_code))) then
  raise exception 'Rekonsiliasi bank sudah mencakup rekening sumber atau tujuan; koreksi rekonsiliasi dahulu';end if;

 -- Saldo rekening asal milik invoice ini harus sama dengan pembayaran yang tercatat di rekening itu.
 select coalesce(sum(l.debit-l.credit),0) into ledger
  from public.journal_entries e join public.journal_lines l on l.entry_id=e.id
  join public.coa_accounts a on a.id=l.account_id
  where e.source_ref=inv.invoice_no and e.voided_at is null and e.branch_id=vis.branch_id
   and e.source in('klinik','klinik-ar','klinik-edit','klinik-reissue','klinik-koreksi-bayar') and a.code=from_code;
 expected:=coalesce((select sum(p.amount) from public.invoice_payments p
   where p.invoice_id=inv.id and p.transferred_from is null and p.kas_code=from_code),0)
  +case when direct>0 and direct_code=from_code then direct else 0 end;
 if ledger<>expected or ledger<amount then
  raise exception 'Jurnal kas/bank invoice tidak cocok dengan pembayaran tercatat; rekonsiliasi diperlukan';end if;

 before_snapshot:=jsonb_build_object('invoice',to_jsonb(inv),'payment',case when p_payment_id is null then null else to_jsonb(pay) end,
  'method',old_method,'code',from_code,'amount',amount);
 journal:=public.clinic_write_journal(today,'Koreksi metode pembayaran '||inv.invoice_no||' ('||old_method||' ke '||p_new_method||')',
  'klinik-koreksi-bayar',inv.invoice_no,vis.branch_id,jsonb_build_array(
   jsonb_build_object('code',to_code,'debit',amount,'credit',0),
   jsonb_build_object('code',from_code,'debit',0,'credit',amount)));
 if journal is null or (select count(*) from public.journal_lines where entry_id=journal)<>2
  or (select coalesce(sum(debit-credit),0) from public.journal_lines where entry_id=journal)<>0 then
  raise exception 'Jurnal koreksi tidak lengkap atau tidak seimbang';end if;

 if p_payment_id is null then
  update public.invoices set metode_bayar=p_new_method where id=inv.id;
  after_snapshot:=jsonb_build_object('invoice',(select to_jsonb(x) from public.invoices x where x.id=inv.id),'payment',null,
   'method',p_new_method,'code',to_code,'amount',amount);
 else
  update public.invoice_payments set metode=p_new_method,kas_code=to_code where id=pay.id;
  after_snapshot:=jsonb_build_object('invoice',to_jsonb(inv),'payment',(select to_jsonb(x) from public.invoice_payments x where x.id=pay.id),
   'method',p_new_method,'code',to_code,'amount',amount);
 end if;

 insert into public.clinic_payment_corrections(id,invoice_id,invoice_payment_id,branch_id,revision,amount,from_method,to_method,
  from_code,to_code,reason,source_shift_id,source_shift_status,before_snapshot,after_snapshot,journal_id,created_by)
  values(audit,inv.id,p_payment_id,vis.branch_id,current_revision+1,amount,old_method,p_new_method,from_code,to_code,
   btrim(p_reason),inv.shift_id,shift_status,before_snapshot,after_snapshot,journal,actor);
 result:=jsonb_build_object('invoice_id',inv.id,'payment_id',p_payment_id,'audit_id',audit,'revision',current_revision+1,
  'journal_id',journal,'method',p_new_method,'amount',amount,'source_shift_status',shift_status);
 insert into public.clinic_payment_correction_requests(actor_id,request_key,invoice_id,payload,result)
  values(actor,p_request_key,inv.id,payload,result);
 return result;
end $$;
revoke all on function public.correct_clinic_invoice_payment(uuid,uuid,integer,text,text,text)
 from public,anon,authenticated,service_role;
grant execute on function public.correct_clinic_invoice_payment(uuid,uuid,integer,text,text,text) to authenticated;

-- Jurnal koreksi klinik sama tetapnya dengan jurnal koreksi POS: tidak dapat
-- dihapus, diubah atau dibatalkan lewat API biasa. Memperluas penanda yang dipakai
-- trigger pos_sale_protect_journal_header/lines yang sudah ada.
do $$ begin
 if to_regprocedure('public.pos_sale_journal_protected(uuid)') is null
  or to_regprocedure('public.pos_sale_protect_journal()') is null then
  raise exception 'J02_CLINIC_GUARD_SOURCE_CHANGED: review journal protection contract';end if;
end $$;
create or replace function public.pos_sale_journal_protected(p_entry uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.pos_sale_postings where revenue_journal_id=p_entry or hpp_journal_id=p_entry)
 or exists(select 1 from public.journal_entries e where e.id=p_entry and e.source in('sale','sale-hpp','sale-online','sale-online-hpp','sale-void','sale-void-hpp','sale-payment-reversal','sale-payment-repost','klinik-koreksi-bayar'))
 or exists(select 1 from public.sale_payment_corrections c where c.reversal_journal_id=p_entry or c.replacement_journal_id=p_entry)
 or exists(select 1 from public.clinic_payment_corrections c where c.journal_id=p_entry)
$$;

-- N01/J01 (keputusan pemilik 29 Okt 2026): Retur Penjualan untuk Faktur Penjualan grosir/B2B.
--
-- Sebelumnya retur hanya ada untuk struk kasir (sales_returns → sales). Faktur grosir yang
-- barangnya dikembalikan pelanggan tidak punya dokumen: koreksi faktur hanya boleh mengubah
-- harga/tempo/catatan, dan perubahan qty "memerlukan rekonsiliasi pengiriman atau retur fisik".
--
-- Dokumen baru: wholesale_returns (+ wholesale_return_items), selalu menunjuk SATU faktur grosir
-- aktif yang sudah diposting dari pesanan (bukan saldo awal, bukan selisih opname).
--
-- Efek satu transaksi (post_wholesale_return):
--  * qty per baris ≤ qty faktur − qty yang sudah diretur (retur aktif);
--  * barang persediaan masuk lagi ke gudang pilihan (cabang faktur) lewat stock_in_fifo pada HPP
--    asal baris faktur (alokasi pengiriman), sama seperti retur struk kasir memulihkan modal;
--    pada mode moving average nilainya ikut tercampur ke rata-rata lewat mutasi yang sama;
--  * jurnal 'wholesale-return' seimbang: Dr 4101 pendapatan bruto, Cr 4102 diskon, Dr 2201 PPN,
--    Cr 1201 piutang (selama faktur masih punya sisa tagihan), Cr 2103 kredit pelanggan (bagian
--    yang sudah dibayar — mekanisme kredit pelanggan grosir yang sama dengan koreksi J01),
--    Dr 1301 persediaan / Cr 5101 HPP senilai modal yang kembali;
--  * piutang faktur berkurang lewat kolom sales_invoices.returned_ar (bukan baris penerimaan,
--    jadi kas/penerimaan tidak tercemar); status lunas dihitung ulang.
-- Nilai pendapatan/diskon/PPN dihitung kumulatif terhadap nilai jurnal faktur, sehingga retur
-- seluruh qty membalik persis jurnal fakturnya (tanpa selisih pembulatan).
--
-- Pembatalan (void_wholesale_return, OWNER/FINANCE): hanya bila lapisan stok retur masih utuh;
-- lapisan dinolkan, mutasi pembalik pada harga asal (moving average memperlakukannya seperti
-- pembatalan penerimaan), jurnal dibalik dengan jurnal baru, piutang/kredit dikembalikan.
--
-- Pengaman lain: faktur dengan retur aktif tidak bisa dibatalkan/diganti/diedit (trigger), jadi
-- koreksi lama tidak bisa diam-diam menagih ulang barang yang sudah kembali. Penerimaan
-- (receive_wholesale_payment/cancel_wholesale_receipt) ikut memperhitungkan returned_ar.
-- Idempoten per (aktor, kunci) lewat wholesale_operation_requests jenis 'return'/'return-void'.

-- ───────────────────────── 1. Skema ─────────────────────────
alter table public.sales_invoices
 add column returned_ar numeric(15,2) not null default 0 check(returned_ar>=0);
comment on column public.sales_invoices.returned_ar is
 'Pengurang piutang dari retur grosir aktif (wholesale_returns.ar_reduction). Sisa = total - carried_paid - returned_ar - penerimaan.';

create table public.wholesale_returns(
 id uuid primary key default gen_random_uuid(),
 no_retur varchar(30) not null unique,
 invoice_id uuid not null references public.sales_invoices(id),
 branch_id uuid references public.branches(id),
 customer_id uuid references public.customers(id),
 warehouse_id uuid references public.warehouses(id),
 tanggal date not null,
 alasan text not null check(length(btrim(alasan)) between 3 and 1000),
 -- Nilai jurnal (rupiah bulat, kumulatif terhadap jurnal faktur).
 gross numeric(15,2) not null check(gross>=0),
 diskon numeric(15,2) not null default 0 check(diskon>=0),
 ppn numeric(15,2) not null default 0 check(ppn>=0),
 total numeric(15,2) not null check(total>=0),
 ar_reduction numeric(15,2) not null check(ar_reduction>=0),
 customer_credit numeric(15,2) not null check(customer_credit>=0),
 hpp numeric(15,2) not null default 0 check(hpp>=0),
 status text not null default 'posted' check(status in ('posted','batal')),
 journal_id uuid not null unique references public.journal_entries(id),
 revision integer not null default 0,
 voided_at timestamptz, voided_on date, void_reason text,
 voided_by uuid references public.profiles(id),
 reversal_journal_id uuid unique references public.journal_entries(id),
 created_by uuid not null references public.profiles(id),
 created_at timestamptz not null default now(),
 check(total=gross-diskon+ppn),
 check(ar_reduction+customer_credit=total),
 check((status='posted' and voided_at is null and reversal_journal_id is null)
  or (status='batal' and voided_at is not null and voided_on is not null and reversal_journal_id is not null and length(btrim(coalesce(void_reason,'')))>=3))
);
create index on public.wholesale_returns(invoice_id);
create index on public.wholesale_returns(customer_id);
create index on public.wholesale_returns(tanggal);

create table public.wholesale_return_items(
 id uuid primary key default gen_random_uuid(),
 return_id uuid not null references public.wholesale_returns(id),
 invoice_item_id uuid not null references public.sales_invoice_items(id),
 item_id uuid references public.items(id),
 nama varchar(160) not null,
 satuan varchar(20),
 faktor numeric not null check(faktor>0),
 qty numeric not null check(qty>0),
 harga numeric(15,2) not null check(harga>=0),
 -- Nilai baris persis (qty × harga dan porsi diskon baris); dasar pembulatan kumulatif.
 gross numeric(15,2) not null check(gross>=0),
 diskon numeric(15,2) not null default 0 check(diskon>=0),
 hpp numeric(15,2) not null default 0 check(hpp>=0),
 stocked boolean not null,
 exp_date date,
 unique(return_id,invoice_item_id)
);
create index on public.wholesale_return_items(invoice_item_id);

alter table public.wholesale_returns enable row level security;
alter table public.wholesale_return_items enable row level security;
revoke all on public.wholesale_returns,public.wholesale_return_items from public,anon,authenticated,service_role;
grant select on public.wholesale_returns,public.wholesale_return_items to authenticated;
-- Visibilitas mengikuti faktur sumbernya (RLS cabang sales_invoices), sama dengan koreksi grosir.
create policy wholesale_returns_read on public.wholesale_returns for select to authenticated
 using(exists(select 1 from public.sales_invoices i where i.id=invoice_id));
create policy wholesale_return_items_read on public.wholesale_return_items for select to authenticated
 using(exists(select 1 from public.wholesale_returns r where r.id=return_id));

-- Dokumen terposting tidak diubah selain transisi pembatalan resmi; baris tidak pernah berubah.
create function public.guard_wholesale_return_record() returns trigger
language plpgsql set search_path='' as $$
begin
 if tg_table_name='wholesale_return_items' or tg_op='DELETE' then
  raise exception 'Retur penjualan grosir terposting tidak dapat diubah atau dihapus; gunakan pembatalan retur' using errcode='42501';
 end if;
 if old.status<>'posted' or new.status<>'batal'
  or (to_jsonb(new)-array['status','revision','voided_at','voided_on','void_reason','voided_by','reversal_journal_id'])
   is distinct from (to_jsonb(old)-array['status','revision','voided_at','voided_on','void_reason','voided_by','reversal_journal_id']) then
  raise exception 'Retur penjualan grosir hanya dapat dibatalkan lewat proses resmi' using errcode='42501';
 end if;
 return new;
end$$;
revoke all on function public.guard_wholesale_return_record() from public,anon,authenticated,service_role;
create trigger wholesale_return_record_guard before update or delete on public.wholesale_returns
 for each row execute function public.guard_wholesale_return_record();
create trigger wholesale_return_item_guard before update or delete on public.wholesale_return_items
 for each row execute function public.guard_wholesale_return_record();

-- returned_ar hanya diubah proses retur (SECURITY DEFINER). Klien tidak boleh menyentuhnya,
-- termasuk pada faktur selisih opname yang memang boleh ditulis klien.
create function public.guard_wholesale_returned_ar() returns trigger
language plpgsql set search_path='' as $$
begin
 if current_user in ('authenticated','anon','service_role')
  and ((tg_op='INSERT' and new.returned_ar<>0) or (tg_op='UPDATE' and new.returned_ar is distinct from old.returned_ar)) then
  raise exception 'Pengurang piutang retur hanya melalui dokumen retur penjualan' using errcode='42501';
 end if;
 return new;
end$$;
revoke all on function public.guard_wholesale_returned_ar() from public,anon,authenticated,service_role;
create trigger wholesale_returned_ar_guard before insert or update of returned_ar on public.sales_invoices
 for each row execute function public.guard_wholesale_returned_ar();

-- Faktur yang punya retur aktif tidak boleh dibatalkan/diganti (koreksi harga, edit baris,
-- pembatalan tagihan). Kalau boleh, faktur pengganti akan menagih lagi barang yang sudah kembali.
create function public.guard_wholesale_invoice_with_return() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.status='batal' and old.status is distinct from 'batal'
  and exists(select 1 from public.wholesale_returns r where r.invoice_id=old.id and r.status='posted') then
  raise exception 'Faktur ini punya retur penjualan aktif. Batalkan returnya dulu sebelum mengoreksi, mengedit atau membatalkan faktur' using errcode='22023';
 end if;
 return new;
end$$;
revoke all on function public.guard_wholesale_invoice_with_return() from public,anon,authenticated,service_role;
create trigger wholesale_invoice_return_guard before update of status on public.sales_invoices
 for each row execute function public.guard_wholesale_invoice_with_return();

-- Jurnal dan mutasi stok retur grosir hanya lewat proses resmi.
create function public.guard_wholesale_return_effect() returns trigger
language plpgsql set search_path='' as $$
declare protected boolean:=false;
begin
 if current_user in ('authenticated','anon','service_role') then
  if tg_table_name='journal_entries' then
   protected:=coalesce(new.source in ('wholesale-return','wholesale-return-void'),false) or coalesce(old.source in ('wholesale-return','wholesale-return-void'),false);
  elsif tg_table_name='journal_lines' then
   protected:=exists(select 1 from public.journal_entries e where e.id in (new.entry_id,old.entry_id) and e.source in ('wholesale-return','wholesale-return-void'));
  else
   protected:=coalesce(new.source in ('wholesale-return','wholesale-return-void'),false) or coalesce(old.source in ('wholesale-return','wholesale-return-void'),false);
  end if;
  if protected then raise exception 'Jurnal/mutasi retur penjualan grosir hanya melalui proses resmi' using errcode='42501';end if;
 end if;
 return coalesce(new,old);
end$$;
revoke all on function public.guard_wholesale_return_effect() from public,anon,authenticated,service_role;
create trigger wholesale_return_journal_guard before insert or update or delete on public.journal_entries
 for each row execute function public.guard_wholesale_return_effect();
create trigger wholesale_return_journal_line_guard before insert or update or delete on public.journal_lines
 for each row execute function public.guard_wholesale_return_effect();
create trigger wholesale_return_stock_move_guard before insert or update or delete on public.stock_moves
 for each row execute function public.guard_wholesale_return_effect();
create trigger wholesale_return_stock_layer_guard before insert or update or delete on public.stock_layers
 for each row execute function public.guard_wholesale_return_effect();

-- Idempotensi ikut tabel permintaan grosir yang sudah ada.
alter table public.wholesale_operation_requests drop constraint wholesale_operation_requests_kind_check;
alter table public.wholesale_operation_requests add constraint wholesale_operation_requests_kind_check
 check(kind in ('receipt','correction','line-edit','receipt-cancel','return','return-void'));

-- ───────────────────── 2. Tambalan fungsi berjalan ─────────────────────
-- Gaya jangkar eksak dan gagal tertutup, sama dengan 20261030120000_faktur_jual_edit_penerimaan.
do $patch$
declare p record; definition text; signature regprocedure; hits integer;
begin
 for p in select * from (values
 -- A. Sisa tagihan saat menerima pembayaran ikut dikurangi retur.
 ('public.receive_wholesale_payment(text,uuid,date,numeric,text,uuid,uuid,text)',1,
  ' select inv.carried_paid+coalesce(sum(jumlah),0) into paid from public.sales_receipts where invoice_id=inv.id;',
  ' select inv.carried_paid+inv.returned_ar+coalesce(sum(jumlah),0) into paid from public.sales_receipts where invoice_id=inv.id;'),
 -- B. Status lunas setelah penerimaan dihapus ikut memperhitungkan retur.
 ('public.cancel_wholesale_receipt(uuid,integer,text,text)',1,
  ' select inv.carried_paid+coalesce(sum(jumlah),0) into paid from public.sales_receipts where invoice_id=inv.id;',
  ' select inv.carried_paid+inv.returned_ar+coalesce(sum(jumlah),0) into paid from public.sales_receipts where invoice_id=inv.id;'),
 -- C. "Periksa hasil terakhir" melayani retur (OWNER/ADMIN/FINANCE) dan pembatalannya (OWNER/FINANCE).
 ('public.get_wholesale_operation(uuid,text,text)',1,
  E'p_kind in (''correction'',''line-edit'',''receipt-cancel'')',
  E'p_kind in (''correction'',''line-edit'',''receipt-cancel'',''return-void'')'),
 ('public.get_wholesale_operation(uuid,text,text)',1,
  E'if p_kind not in (''receipt'',''correction'',''line-edit'',''receipt-cancel'') then',
  E'if p_kind not in (''receipt'',''correction'',''line-edit'',''receipt-cancel'',''return'',''return-void'') then'),
 -- D. Moving average: mutasi pembatalan retur mengeluarkan nilai pada harga asal retur.
 ('public.inventory_record_valuation()',1,
  E'new.source in(''purchase-invoice-void'',''purchase-receipt-void'')',
  E'new.source in(''purchase-invoice-void'',''purchase-receipt-void'',''wholesale-return-void'')')
 ) as patches(sig,expected,old_text,new_text) loop
  signature:=to_regprocedure(p.sig);
  if signature is null then raise exception 'Retur grosir: RPC wajib tidak ada: %',p.sig;end if;
  definition:=pg_get_functiondef(signature);
  hits:=(length(definition)-length(replace(definition,p.old_text,'')))/length(p.old_text);
  if hits<>p.expected then
   raise exception 'Retur grosir: jangkar harus muncul % kali di % (ketemu %); periksa definisi sebelum menerapkan',p.expected,p.sig,hits;
  end if;
  execute replace(definition,p.old_text,p.new_text);
 end loop;
end $patch$;

revoke all on function public.receive_wholesale_payment(text,uuid,date,numeric,text,uuid,uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.receive_wholesale_payment(text,uuid,date,numeric,text,uuid,uuid,text) to authenticated;
revoke all on function public.cancel_wholesale_receipt(uuid,integer,text,text) from public,anon,service_role;
grant execute on function public.cancel_wholesale_receipt(uuid,integer,text,text) to authenticated;
revoke all on function public.get_wholesale_operation(uuid,text,text) from public,anon,authenticated,service_role;
grant execute on function public.get_wholesale_operation(uuid,text,text) to authenticated;
revoke all on function public.inventory_record_valuation() from public,anon,authenticated,service_role;

-- ───────────────────── 3. Posting retur ─────────────────────
create function public.post_wholesale_return(
 p_request_key text,p_invoice_id uuid,p_tanggal date,p_warehouse_id uuid,p_alasan text,p_items jsonb
) returns jsonb language plpgsql security definer set search_path='' set lock_timeout='8s' as $$
declare
 inv public.sales_invoices%rowtype;ord public.sales_orders%rowtype;prior public.wholesale_operation_requests%rowtype;
 line public.sales_invoice_items%rowtype;item record;r record;
 payload jsonb;result jsonb;lines jsonb;rows jsonb:='[]';v_doc uuid:=gen_random_uuid();v_no text;v_prefix text;v_digits integer;v_seq bigint;
 v_journal uuid;v_original uuid;v_order uuid;v_wh_branch uuid;v_type text;
 src_gross numeric;src_disc numeric;booked_gross numeric;booked_disc numeric;
 prev_qty numeric;prev_disc numeric;prev_hpp numeric;v_disc numeric;v_hpp numeric;v_base numeric;v_stocked boolean;v_count integer;
 prev_line_gross numeric;prev_line_disc numeric;prev_g numeric;prev_d numeric;prev_p numeric;
 cum_gross numeric;cum_disc numeric;g_after numeric;d_after numeric;p_after numeric;
 v_gross numeric:=0;v_disc_total numeric:=0;v_line_gross numeric:=0;v_line_disc numeric:=0;v_ppn numeric;v_total numeric;v_hpp_total numeric:=0;
 v_paid numeric;v_outstanding numeric;v_ar numeric;v_credit numeric;v_needs_wh boolean:=false;
begin
 select order_id into v_order from public.sales_invoices where id=p_invoice_id;
 -- Urutan kunci sama dengan penerimaan/koreksi grosir: pesanan → faktur.
 if v_order is not null then select * into ord from public.sales_orders where id=v_order for update;end if;
 select * into inv from public.sales_invoices where id=p_invoice_id for update;
 if not found then raise exception 'Faktur grosir tidak ditemukan' using errcode='42501';end if;
 perform public.wholesale_access(inv.branch_id,false);
 if p_request_key is null or length(btrim(p_request_key)) not between 1 and 120 or p_request_key like 'preview:%'
  or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)=0 then
  raise exception 'Identitas atau rincian retur tidak valid' using errcode='22023';end if;
 payload:=jsonb_build_object('invoice_id',p_invoice_id,'tanggal',p_tanggal,'warehouse_id',p_warehouse_id,'alasan',btrim(coalesce(p_alasan,'')),'items',p_items);
 perform pg_advisory_xact_lock(hashtextextended('kamo:wholesale:return:'||auth.uid()::text||':'||p_request_key,0));
 select * into prior from public.wholesale_operation_requests where actor_id=auth.uid() and kind='return' and request_key=p_request_key;
 if found then
  if prior.payload is distinct from payload then raise exception 'Identitas retur dipakai untuk rincian berbeda' using errcode='22023';end if;
  return prior.result;
 end if;

 if inv.order_id is null or coalesce(inv.kategori,'penjualan')='selisih_stok' or inv.opening_batch_id is not null
  or ord.id is null or ord.branch_id is distinct from inv.branch_id or ord.customer_id is distinct from inv.customer_id then
  raise exception 'Retur hanya untuk faktur penjualan grosir dari pesanan (bukan saldo awal atau selisih stok)' using errcode='22023';end if;
 if inv.status='batal' then raise exception 'Faktur sudah dibatalkan; buat retur dari faktur penggantinya' using errcode='22023';end if;
 if exists(select 1 from public.sales_invoices where replaces_invoice_id=inv.id) then raise exception 'Faktur ini sudah diganti faktur lain; buka faktur terbaru' using errcode='22023';end if;
 if length(btrim(coalesce(p_alasan,''))) not between 3 and 1000 then raise exception 'Alasan retur wajib diisi (minimal 3 huruf)' using errcode='22023';end if;
 if p_tanggal is null or not isfinite(p_tanggal) then raise exception 'Tanggal retur tidak valid' using errcode='22023';end if;
 perform public.wholesale_period(inv.tanggal,p_tanggal);
 if p_tanggal<inv.tanggal then raise exception 'Tanggal retur mendahului tanggal faktur' using errcode='22023';end if;

 for item in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(item.value) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item.value) k where k not in ('invoice_item_id','qty','exp_date')) then
   raise exception 'Rincian retur hanya baris faktur, qty dan tanggal kedaluwarsa' using errcode='22023';end if;
 end loop;
 select count(*),count(distinct x.invoice_item_id) into v_count,prev_qty from jsonb_to_recordset(p_items) as x(invoice_item_id uuid,qty numeric,exp_date date);
 if v_count<>prev_qty or exists(select 1 from jsonb_to_recordset(p_items) as x(invoice_item_id uuid) where x.invoice_item_id is null) then
  raise exception 'Pilih baris faktur dan jangan gandakan baris yang sama' using errcode='22023';end if;

 -- Bukti sumber: alokasi pengiriman/HPP baris faktur dan jurnal faktur harus utuh.
 if not exists(select 1 from public.sales_invoice_items where invoice_id=inv.id) or exists(
  select 1 from public.sales_invoice_items ii where ii.invoice_id=inv.id and (
   ii.qty<>(select coalesce(sum(a.qty),0) from public.sales_invoice_delivery_allocations a where a.invoice_item_id=ii.id)
   or coalesce(ii.hpp,0)<>(select coalesce(sum(a.hpp),0) from public.sales_invoice_delivery_allocations a where a.invoice_item_id=ii.id))) then
  raise exception 'Alokasi pengiriman/HPP faktur belum terbukti. Rekonsiliasi faktur dan pengiriman dahulu';end if;
 select coalesce(sum(qty*harga),0),coalesce(sum(coalesce(diskon,0)),0) into src_gross,src_disc from public.sales_invoice_items where invoice_id=inv.id;
 if inv.dpp is distinct from src_gross-src_disc or inv.total<>round(inv.dpp)+inv.ppn then
  raise exception 'Nilai baris/faktur tidak cocok dengan pembukuan; rekonsiliasi sumber dahulu';end if;
 booked_gross:=round(src_gross);booked_disc:=round(src_disc);
 lock table public.journal_entries in row exclusive mode;
 if (select count(*) from public.journal_entries where source='sales-invoice' and source_ref=inv.no_faktur)<>1 then raise exception 'Tautan jurnal faktur tidak unik; rekonsiliasi sumber dahulu';end if;
 select id into v_original from public.journal_entries where source='sales-invoice' and source_ref=inv.no_faktur;
 lines:=jsonb_build_array(jsonb_build_object('code','1201','debit',inv.total,'credit',0),jsonb_build_object('code','4101','debit',0,'credit',booked_gross));
 if src_disc>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','4102','debit',booked_disc,'credit',0));end if;
 if inv.ppn>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','2201','debit',0,'credit',inv.ppn));end if;
 perform public.wholesale_assert_journal(v_original,'sales-invoice',inv.no_faktur,inv.tanggal,inv.branch_id,lines);

 -- Retur aktif sebelumnya pada faktur ini (sudah serial di bawah kunci faktur).
 select coalesce(sum(gross),0),coalesce(sum(diskon),0),coalesce(sum(ppn),0) into prev_g,prev_d,prev_p
  from public.wholesale_returns where invoice_id=inv.id and status='posted';
 select coalesce(sum(ri.gross),0),coalesce(sum(ri.diskon),0) into prev_line_gross,prev_line_disc
  from public.wholesale_return_items ri join public.wholesale_returns rt on rt.id=ri.return_id where rt.invoice_id=inv.id and rt.status='posted';

 for item in select * from jsonb_to_recordset(p_items) as x(invoice_item_id uuid,qty numeric,exp_date date) order by invoice_item_id loop
  select * into line from public.sales_invoice_items where id=item.invoice_item_id and invoice_id=inv.id;
  if not found then raise exception 'Baris retur bukan milik faktur ini' using errcode='22023';end if;
  if item.qty is null or item.qty<=0 or item.qty>1000000000 or item.qty::text in ('NaN','Infinity','-Infinity') then
   raise exception 'Qty retur % tidak valid',line.nama using errcode='22023';end if;
  if item.exp_date is not null and not isfinite(item.exp_date) then raise exception 'Tanggal kedaluwarsa % tidak valid',line.nama using errcode='22023';end if;
  select coalesce(sum(ri.qty),0),coalesce(sum(ri.diskon),0),coalesce(sum(ri.hpp),0) into prev_qty,prev_disc,prev_hpp
   from public.wholesale_return_items ri join public.wholesale_returns rt on rt.id=ri.return_id
   where ri.invoice_item_id=line.id and rt.status='posted';
  if item.qty>line.qty-prev_qty then
   raise exception 'Qty retur % melebihi sisa yang bisa diretur (maksimal % %)',line.nama,
    trim(to_char(greatest(line.qty-prev_qty,0),'FM999999999990.######'),'.'),coalesce(line.satuan,'') using errcode='22003';end if;
  select line.item_id is not null and coalesce(i.item_type,'Persediaan')='Persediaan' into v_stocked from public.items i where i.id=line.item_id;
  v_stocked:=coalesce(v_stocked,false);
  if v_stocked and line.hpp is null then raise exception 'HPP baris % belum tersedia; rekonsiliasi faktur dahulu',line.nama;end if;
  if line.faktor is null or line.faktor<=0 then raise exception 'Faktor satuan baris % tidak valid; rekonsiliasi dahulu',line.nama;end if;
  -- Porsi diskon dan HPP dibulatkan kumulatif per baris: retur penuh = nilai baris persis.
  v_disc:=round(coalesce(line.diskon,0)*(prev_qty+item.qty)/line.qty,2)-prev_disc;
  v_hpp:=case when v_stocked then round(coalesce(line.hpp,0)*(prev_qty+item.qty)/line.qty,2)-prev_hpp else 0 end;
  if v_disc<0 or v_hpp<0 then raise exception 'Porsi diskon/HPP retur % tidak konsisten; rekonsiliasi dahulu',line.nama;end if;
  v_base:=item.qty*line.faktor;
  if v_stocked then v_needs_wh:=true;end if;
  v_line_gross:=v_line_gross+round(item.qty*line.harga,2);v_line_disc:=v_line_disc+v_disc;v_hpp_total:=v_hpp_total+v_hpp;
  rows:=rows||jsonb_build_array(jsonb_build_object('invoice_item_id',line.id,'item_id',line.item_id,'nama',line.nama,'satuan',line.satuan,
   'faktor',line.faktor,'qty',item.qty,'harga',line.harga,'gross',round(item.qty*line.harga,2),'diskon',v_disc,'hpp',v_hpp,
   'stocked',v_stocked,'exp_date',item.exp_date,'base',v_base));
 end loop;

 -- Nilai jurnal kumulatif terhadap jurnal faktur: retur seluruh qty = pembalik persis.
 cum_gross:=prev_line_gross+v_line_gross;cum_disc:=prev_line_disc+v_line_disc;
 g_after:=case when src_gross>0 then round(booked_gross*least(cum_gross,src_gross)/src_gross) else 0 end;
 d_after:=case when src_disc>0 then round(booked_disc*least(cum_disc,src_disc)/src_disc) else 0 end;
 p_after:=case when inv.ppn>0 and inv.dpp>0 then round(inv.ppn*least(cum_gross-cum_disc,inv.dpp)/inv.dpp) else 0 end;
 v_gross:=greatest(g_after-prev_g,0);v_disc_total:=greatest(d_after-prev_d,0);v_ppn:=greatest(p_after-prev_p,0);
 v_total:=v_gross-v_disc_total+v_ppn;
 if v_total<0 then raise exception 'Nilai retur negatif; rekonsiliasi diskon faktur dahulu';end if;
 if v_total=0 and v_hpp_total=0 then raise exception 'Nilai retur nol; tidak ada yang perlu dibukukan' using errcode='22023';end if;

 -- Piutang faktur dulu; kelebihan (faktur sudah dibayar) menjadi kredit pelanggan 2103.
 select inv.carried_paid+inv.returned_ar+coalesce(sum(jumlah),0) into v_paid from public.sales_receipts where invoice_id=inv.id;
 v_outstanding:=greatest(inv.total-v_paid,0);
 v_ar:=least(v_total,v_outstanding);v_credit:=v_total-v_ar;
 if v_credit>0 and inv.customer_id is null then raise exception 'Kredit pelanggan memerlukan identitas pelanggan; rekonsiliasi sumber dahulu';end if;

 if v_needs_wh then
  if p_warehouse_id is null then raise exception 'Pilih gudang penerima barang retur' using errcode='22023';end if;
  select branch_id into v_wh_branch from public.warehouses where id=p_warehouse_id and is_active
   and (inv.branch_id is null or branch_id=inv.branch_id) for share;
  if not found then raise exception 'Pilih gudang aktif pada cabang faktur untuk menerima barang retur' using errcode='22023';end if;
  perform public.sales_assert_access(v_wh_branch);
 end if;
 -- Retur jasa saja tidak menyentuh gudang; gudang yang dikirim formulir diabaikan (tidak disimpan).

 -- Nomor RJG (format bisa diatur di Penomoran Dokumen), unik lintas cabang.
 select pola,digit into v_prefix,v_digits from public.document_numbering where jenis='RJG';
 v_prefix:=coalesce(v_prefix,'RJG.{YYYY}.{MM}.');v_digits:=coalesce(v_digits,5);
 v_prefix:=replace(replace(replace(replace(v_prefix,'{YYYY}',to_char(p_tanggal,'YYYY')),'{YY}',to_char(p_tanggal,'YY')),'{MM}',to_char(p_tanggal,'MM')),'{DD}',to_char(p_tanggal,'DD'));
 if v_digits not between 1 and 8 or length(v_prefix)+v_digits>30 then raise exception 'Format nomor retur terlalu panjang';end if;
 perform pg_advisory_xact_lock(hashtextextended('kamo:wholesale:return-number:'||v_prefix,0));
 select coalesce(max(substring(no_retur from length(v_prefix)+1 for v_digits)::bigint),0)+1 into v_seq from public.wholesale_returns
  where left(no_retur,length(v_prefix))=v_prefix and substring(no_retur from length(v_prefix)+1 for v_digits)~'^[0-9]+$';
 if length(v_seq::text)>v_digits then raise exception 'Urutan nomor retur penuh';end if;
 v_no:=v_prefix||lpad(v_seq::text,v_digits,'0');

 lines:=jsonb_build_array(jsonb_build_object('code','4101','debit',v_gross,'credit',0));
 if v_disc_total>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','4102','debit',0,'credit',v_disc_total));end if;
 if v_ppn>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','2201','debit',v_ppn,'credit',0));end if;
 if v_ar>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','1201','debit',0,'credit',v_ar));end if;
 if v_credit>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','2103','debit',0,'credit',v_credit));end if;
 if v_hpp_total>0 then lines:=lines||jsonb_build_array(jsonb_build_object('code','1301','debit',v_hpp_total,'credit',0),jsonb_build_object('code','5101','debit',0,'credit',v_hpp_total));end if;
 v_journal:=public.wholesale_write_journal(p_tanggal,inv.branch_id,'wholesale-return',v_no,
  'Retur penjualan '||v_no||' atas '||inv.no_faktur||': '||btrim(p_alasan),lines);

 insert into public.wholesale_returns(id,no_retur,invoice_id,branch_id,customer_id,warehouse_id,tanggal,alasan,gross,diskon,ppn,total,
  ar_reduction,customer_credit,hpp,journal_id,created_by)
  values(v_doc,v_no,inv.id,inv.branch_id,inv.customer_id,case when v_needs_wh then p_warehouse_id end,p_tanggal,btrim(p_alasan),v_gross,v_disc_total,v_ppn,v_total,
  v_ar,v_credit,v_hpp_total,v_journal,auth.uid());
 -- Barang kembali ke gudang pada HPP asal; urutan per barang menjaga urutan kunci saldo stok.
 for r in select * from jsonb_to_recordset(rows) as x(invoice_item_id uuid,item_id uuid,nama text,satuan text,faktor numeric,qty numeric,harga numeric,
   gross numeric,diskon numeric,hpp numeric,stocked boolean,exp_date date,base numeric) order by item_id nulls last,invoice_item_id loop
  insert into public.wholesale_return_items(return_id,invoice_item_id,item_id,nama,satuan,faktor,qty,harga,gross,diskon,hpp,stocked,exp_date)
   values(v_doc,r.invoice_item_id,r.item_id,r.nama,r.satuan,r.faktor,r.qty,r.harga,r.gross,r.diskon,r.hpp,r.stocked,r.exp_date);
  if r.stocked then
   perform public.stock_in_fifo(p_warehouse_id,r.item_id,r.base,r.hpp/r.base,'wholesale-return',v_no,p_tanggal,r.exp_date);
  end if;
 end loop;

 update public.sales_invoices set returned_ar=returned_ar+v_ar,
  status=case when v_paid+v_ar>=total then 'lunas' else 'berjalan' end,revision=revision+1 where id=inv.id;
 -- Periksa ulang hak akses setelah semua kunci, sama dengan proses grosir lain.
 perform public.wholesale_access(inv.branch_id,false);
 result:=jsonb_build_object('return_id',v_doc,'document_no',v_no,'invoice_id',inv.id,'journal_id',v_journal,
  'total',v_total,'ar_reduction',v_ar,'customer_credit',v_credit,'hpp',v_hpp_total);
 insert into public.wholesale_operation_requests(actor_id,kind,request_key,invoice_id,payload,result)
  values(auth.uid(),'return',p_request_key,inv.id,payload,result);
 return result;
end$$;
revoke all on function public.post_wholesale_return(text,uuid,date,uuid,text,jsonb) from public,anon,service_role;
grant execute on function public.post_wholesale_return(text,uuid,date,uuid,text,jsonb) to authenticated;

-- ───────────────────── 4. Pembatalan retur ─────────────────────
create function public.void_wholesale_return(p_return_id uuid,p_expected_revision integer,p_request_key text,p_reason text) returns jsonb
language plpgsql security definer set search_path='' set lock_timeout='8s' as $$
declare
 ret public.wholesale_returns%rowtype;inv public.sales_invoices%rowtype;prior public.wholesale_operation_requests%rowtype;
 r record;payload jsonb;result jsonb;lines jsonb;moves jsonb;layers jsonb;v_invoice uuid;v_order uuid;v_reversal uuid;v_paid numeric;
 today date:=(now() at time zone 'Asia/Jakarta')::date;
 consumed constant text:='Barang dari retur ini sudah terpakai atau keluar dari gudang, jadi retur tidak bisa dibatalkan otomatis. Minta keuangan merekonsiliasi.';
begin
 select invoice_id into v_invoice from public.wholesale_returns where id=p_return_id;
 if not found then raise exception 'Retur penjualan tidak ditemukan' using errcode='42501';end if;
 -- Urutan kunci sama dengan posting retur: pesanan → faktur → retur.
 select order_id into v_order from public.sales_invoices where id=v_invoice;
 if v_order is not null then perform 1 from public.sales_orders where id=v_order for update;end if;
 select * into inv from public.sales_invoices where id=v_invoice for update;
 select * into ret from public.wholesale_returns where id=p_return_id for update;
 perform public.wholesale_access(inv.branch_id,true);
 if p_request_key is null or length(btrim(p_request_key)) not between 1 and 120 or p_expected_revision is null or p_expected_revision<0
  or length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then raise exception 'Identitas atau alasan pembatalan retur tidak valid' using errcode='22023';end if;
 payload:=jsonb_build_object('return_id',p_return_id,'revision',p_expected_revision,'reason',btrim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('kamo:wholesale:return-void:'||auth.uid()::text||':'||p_request_key,0));
 select * into prior from public.wholesale_operation_requests where actor_id=auth.uid() and kind='return-void' and request_key=p_request_key;
 if found then
  if prior.payload is distinct from payload then raise exception 'Identitas pembatalan dipakai untuk rincian berbeda' using errcode='22023';end if;
  return prior.result;
 end if;
 if ret.status<>'posted' then raise exception 'Retur ini sudah dibatalkan';end if;
 if ret.revision<>p_expected_revision then raise exception 'Retur sudah berubah. Muat ulang sebelum membatalkan' using errcode='40001';end if;
 perform public.wholesale_period(ret.tanggal,today);

 -- Jurnal retur harus persis seperti dokumennya sebelum dibalik.
 lock table public.journal_entries in row exclusive mode;
 lines:=jsonb_build_array(jsonb_build_object('code','4101','debit',ret.gross,'credit',0),
  jsonb_build_object('code','4102','debit',0,'credit',ret.diskon),jsonb_build_object('code','2201','debit',ret.ppn,'credit',0),
  jsonb_build_object('code','1201','debit',0,'credit',ret.ar_reduction),jsonb_build_object('code','2103','debit',0,'credit',ret.customer_credit),
  jsonb_build_object('code','1301','debit',ret.hpp,'credit',0),jsonb_build_object('code','5101','debit',0,'credit',ret.hpp));
 perform public.wholesale_assert_journal(ret.journal_id,'wholesale-return',ret.no_retur,ret.tanggal,inv.branch_id,lines);
 if inv.returned_ar<ret.ar_reduction then raise exception 'Pengurang piutang faktur tidak cocok dengan retur; rekonsiliasi dahulu';end if;

 -- Stok: lapisan retur harus utuh dan saldo cukup; kunci saldo agregat sebelum lapisan.
 if exists(select 1 from public.wholesale_return_items where return_id=ret.id and stocked) then
  for r in select distinct item_id from public.wholesale_return_items where return_id=ret.id and stocked order by item_id loop
   perform 1 from public.stock where warehouse_id=ret.warehouse_id and item_id=r.item_id for update;
  end loop;
  select coalesce(jsonb_agg(to_jsonb(m) order by m.item_id,m.id),'[]') into moves from public.stock_moves m
   where m.warehouse_id=ret.warehouse_id and m.source='wholesale-return' and m.source_ref=ret.no_retur;
  perform 1 from public.stock_layers l where l.warehouse_id=ret.warehouse_id and l.source='wholesale-return' and l.source_ref=ret.no_retur order by l.id for update;
  select coalesce(jsonb_agg(to_jsonb(l) order by l.item_id,l.id),'[]') into layers from public.stock_layers l
   where l.warehouse_id=ret.warehouse_id and l.source='wholesale-return' and l.source_ref=ret.no_retur;
  for r in select ri.item_id,sum(ri.qty*ri.faktor) expected,
    coalesce((select sum((x->>'qty')::numeric) from jsonb_array_elements(moves) x where (x->>'item_id')::uuid=ri.item_id),0) moved,
    coalesce((select sum((x->>'qty_in')::numeric) from jsonb_array_elements(layers) x where (x->>'item_id')::uuid=ri.item_id),0) layered,
    coalesce((select bool_and((x->>'qty_left')::numeric=(x->>'qty_in')::numeric) from jsonb_array_elements(layers) x where (x->>'item_id')::uuid=ri.item_id),true) untouched
   from public.wholesale_return_items ri where ri.return_id=ret.id and ri.stocked group by ri.item_id order by ri.item_id loop
   if r.moved<>r.expected then raise exception 'Mutasi stok retur tidak cocok dengan dokumennya; rekonsiliasi dahulu';end if;
   if r.layered<>r.moved or not r.untouched then raise exception '%',consumed;end if;
  end loop;
  update public.stock_layers set qty_left=0 where id in (select (x->>'id')::uuid from jsonb_array_elements(layers) x);
  for r in select (x->>'item_id')::uuid item_id,sum((x->>'qty')::numeric) qty,sum((x->>'qty')::numeric*(x->>'unit_cost')::numeric) val
    from jsonb_array_elements(moves) x group by 1 order by 1 loop
   update public.stock set qty=qty-r.qty,updated_at=now() where warehouse_id=ret.warehouse_id and item_id=r.item_id and qty>=r.qty;
   if not found then raise exception '%',consumed;end if;
   insert into public.stock_moves(tanggal,warehouse_id,item_id,qty,unit_cost,source,source_ref)
    values(today,ret.warehouse_id,r.item_id,-r.qty,r.val/r.qty,'wholesale-return-void',ret.no_retur);
  end loop;
 end if;

 select jsonb_agg(jsonb_build_object('code',a.code,'debit',l.credit,'credit',l.debit)) into lines
  from public.journal_lines l join public.coa_accounts a on a.id=l.account_id where l.entry_id=ret.journal_id;
 v_reversal:=public.wholesale_write_journal(today,inv.branch_id,'wholesale-return-void',ret.id::text,
  'Pembatalan retur '||ret.no_retur||' atas '||inv.no_faktur||': '||btrim(p_reason),lines);
 update public.wholesale_returns set status='batal',voided_at=now(),voided_on=today,void_reason=btrim(p_reason),voided_by=auth.uid(),
  reversal_journal_id=v_reversal,revision=revision+1 where id=ret.id;
 select inv.carried_paid+(inv.returned_ar-ret.ar_reduction)+coalesce(sum(jumlah),0) into v_paid from public.sales_receipts where invoice_id=inv.id;
 update public.sales_invoices set returned_ar=returned_ar-ret.ar_reduction,
  status=case when status='batal' then status when v_paid>=total then 'lunas' else 'berjalan' end,revision=revision+1 where id=inv.id;
 perform public.wholesale_access(inv.branch_id,true);
 result:=jsonb_build_object('return_id',ret.id,'document_no',ret.no_retur,'invoice_id',inv.id,'reversal_journal_id',v_reversal,
  'ar_restored',ret.ar_reduction,'credit_reversed',ret.customer_credit,'tanggal',today);
 insert into public.wholesale_operation_requests(actor_id,kind,request_key,invoice_id,payload,result)
  values(auth.uid(),'return-void',p_request_key,inv.id,payload,result);
 return result;
end$$;
revoke all on function public.void_wholesale_return(uuid,integer,text,text) from public,anon,service_role;
grant execute on function public.void_wholesale_return(uuid,integer,text,text) to authenticated;

-- ───────────────────── 5. Log aktivitas (A01) ─────────────────────
insert into public.activity_log_sources
 (entity,module_id,label_key,value_keys,scope_kind,identity_keys,branch_columns,scope_parents,metadata_only,parent_entity,parent_key,reader_roles)
values
 ('wholesale_returns','penjualan','no_retur',array['tanggal','total','ar_reduction','customer_credit','hpp','status','voided_on','revision'],
  'refs',array['id'],array['branch_id'],'[{"entity":"sales_invoices","key":"invoice_id"}]',false,null,null,array['OWNER','ADMIN']),
 ('wholesale_return_items','penjualan',null,array['qty','harga','gross','diskon','hpp'],
  'refs',array['id'],'{}','[{"entity":"wholesale_returns","key":"return_id"},{"entity":"sales_invoice_items","key":"invoice_item_id"}]',false,'wholesale_returns','return_id',array['OWNER','ADMIN'])
on conflict (entity) do nothing;
create trigger a01_activity_change after insert or update on public.wholesale_returns for each row execute function public.capture_activity_log();
create trigger a01_activity_delete before delete on public.wholesale_returns for each row execute function public.capture_activity_log();
create trigger a01_activity_change after insert or update on public.wholesale_return_items for each row execute function public.capture_activity_log();
create trigger a01_activity_delete before delete on public.wholesale_return_items for each row execute function public.capture_activity_log();

-- K08 (keputusan owner 29 Okt): kunjungan yang masih punya tagihan klinik AKTIF tidak boleh
-- langsung masuk rawat inap.
--   * Tagihan aktif belum lunas (Belum Lunas / DP): lunasi atau batalkan (void) dulu.
--     Setelah lunas -> "Lanjutkan ke Rawat Inap" (kunjungan lanjutan K06, PR #276).
--     Setelah di-void -> kunjungan bisa dimasukkan langsung seperti biasa.
--   * Tagihan aktif sudah lunas: selalu lewat kunjungan lanjutan (K06), tidak pernah langsung.
-- Dulu jalur langsung tetap terbuka untuk tagihan belum lunas, sehingga rawat inap terbuka di
-- kunjungan yang tagihannya sudah terbit: pasien tidak bisa dipulangkan (INVOICE_EXISTS) dan
-- biaya inap tidak bisa ditagih.
--
-- Diterapkan di clinic_admit_inpatient (dipakai juga oleh clinic_admit_inpatient_typed untuk
-- tipe 'sakit'). Pesan penolakan lanjutan K06 untuk tagihan belum lunas ikut diperjelas.
-- Signature, SECURITY DEFINER, search_path, owner dan grant sama; peran sesi dibaca lewat
-- auth.role() (perbaikan 20261031095000). Tidak ada tabel, kolom atau data yang diubah.

create or replace function public.clinic_admit_inpatient(p_visit_id uuid,p_treatment_plan text,p_request_key text)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_visit public.visits%rowtype;v_existing public.inpatient_records%rowtype;
  v_key text:=nullif(btrim(p_request_key),'');v_plan text:=nullif(btrim(p_treatment_plan),'');
  v_hash text;v_medical uuid;v_consent uuid;v_template uuid;v_required boolean;v_id uuid;
begin
  if coalesce(auth.role(),'')<>'authenticated' or auth.uid() is null or not exists(
    select 1 from public.profiles where id=auth.uid() and is_active
  ) then raise exception 'ACCESS_DENIED: pengguna tidak aktif atau tidak terautentikasi';end if;
  if v_key is null or length(v_key)>100 or v_plan is null or length(v_plan)>4000 then
    raise exception 'ADMISSION_INVALID: isi rencana tindakan dan muat ulang formulir';end if;
  select * into v_visit from public.visits where id=p_visit_id for update;
  if not found or not public.user_can_access_branch(v_visit.branch_id) then
    raise exception 'ACCESS_DENIED: kunjungan atau cabang tidak dapat diakses';end if;
  v_hash:=md5(jsonb_build_object('visit',p_visit_id,'plan',v_plan,'actor',auth.uid())::text);
  select * into v_existing from public.inpatient_records where admission_request_key=v_key;
  if found then
    if v_existing.admission_request_hash is distinct from v_hash then
      raise exception 'IDEMPOTENCY_CONFLICT: kunci masuk rawat inap dipakai untuk data berbeda';end if;
    return v_existing.id;
  end if;
  if exists(select 1 from public.inpatient_records where visit_id=p_visit_id and discharged_at is null) then
    raise exception 'ADMISSION_INVALID: pasien sudah memiliki rawat inap aktif';end if;
  if v_visit.checked_out_at is not null or v_visit.status='Selesai' then
    raise exception 'ADMISSION_INVALID: kunjungan sudah selesai';end if;
  -- K08: an active invoice closes the direct path (the visit row lock above also serializes
  -- invoice posting, which locks the same visit first).
  if exists(select 1 from public.invoices where visit_id=p_visit_id and voided_at is null and paid_status='Lunas') then
    raise exception 'ADMISSION_INVALID: tagihan kunjungan ini sudah lunas; gunakan Lanjutkan ke Rawat Inap';end if;
  if exists(select 1 from public.invoices where visit_id=p_visit_id and voided_at is null) then
    raise exception 'ADMISSION_INVALID: tagihan kunjungan ini belum lunas; lunasi atau batalkan tagihan terlebih dahulu sebelum masuk rawat inap';end if;
  select id into v_medical from public.medical_records where visit_id=p_visit_id order by created_at desc limit 1;
  if v_medical is null or v_visit.doctor_id is null then raise exception 'ADMISSION_INVALID: selesaikan pemeriksaan dan pilih dokter terlebih dahulu';end if;
  perform public.clinic_staff_name(v_visit.doctor_id,v_visit.branch_id,'doctor');
  select wajib,template_id into v_required,v_template from public.consent_rules where kategori='Rawat Inap';
  v_required:=coalesce(v_required,true);
  select id into v_consent from public.consents where visit_id=p_visit_id and status='sudah_ttd'
    and kategori='Rawat Inap' and (v_template is null or template_id=v_template)
    order by signed_at desc,id limit 1 for share;
  if v_required and v_consent is null then raise exception 'CONSENT_REQUIRED: tandatangani persetujuan khusus rawat inap terlebih dahulu';end if;
  insert into public.inpatient_records(branch_id,visit_id,medical_record_id,doctor_id,doctor_name,treatment_plan,
    created_by,consent_id,admission_request_key,admission_request_hash)
  values(v_visit.branch_id,p_visit_id,v_medical,v_visit.doctor_id,v_visit.dokter,v_plan,auth.uid(),v_consent,v_key,v_hash)
  returning id into v_id;
  insert into public.inpatient_status_log(inpatient_record_id,previous_status,new_status,changed_by,notes)
  values(v_id,null,'stabil',auth.uid(),'Admit rawat inap');
  return v_id;
end $$;
revoke all on function public.clinic_admit_inpatient(uuid,text,text) from public,anon,service_role;
grant execute on function public.clinic_admit_inpatient(uuid,text,text) to authenticated;

-- K06 continuation: same rules as 20261028120000; only the refusal for a visit that is still
-- open with an unpaid invoice now names the real next step (pay or void, not "admit directly").
create or replace function public.clinic_continue_visit_to_inpatient(p_visit_id uuid, p_request_key text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_visit public.visits%rowtype;
  v_medical public.medical_records%rowtype;
  v_existing public.medical_records%rowtype;
  v_key text := nullif(btrim(p_request_key), '');
  v_submission text;
  v_new_visit uuid;
  v_now timestamptz := now();
begin
  if coalesce(auth.role(), '') <> 'authenticated' or auth.uid() is null or not exists(
    select 1 from public.profiles where id = auth.uid() and is_active
  ) then raise exception 'ACCESS_DENIED: pengguna tidak aktif atau tidak terautentikasi'; end if;
  if not public.inpatient_clinic_module_access() then
    raise exception 'ACCESS_DENIED: peran ini tidak memiliki akses modul klinik'; end if;
  if v_key is null or length(v_key) > 100 then
    raise exception 'ADMISSION_INVALID: muat ulang formulir rawat inap'; end if;
  v_submission := 'k06-continue:' || v_key;

  -- Visit then pet: serializes concurrent clicks on this visit and admissions of this patient.
  select * into v_visit from public.visits where id = p_visit_id for update;
  if not found or not public.user_can_access_branch(v_visit.branch_id) then
    raise exception 'ACCESS_DENIED: kunjungan atau cabang tidak dapat diakses'; end if;
  perform 1 from public.pets where id = v_visit.pet_id for no key update;

  select * into v_existing from public.medical_records where submission_key = v_submission;
  if found then
    if v_existing.submitted_by is distinct from auth.uid() or not exists(
      select 1 from public.visits where id = v_existing.visit_id and continued_from_visit_id = p_visit_id
    ) then raise exception 'IDEMPOTENCY_CONFLICT: kunci lanjutan rawat inap dipakai untuk data berbeda'; end if;
    return v_existing.visit_id;
  end if;

  if not (v_visit.status = 'Selesai' or v_visit.checked_out_at is not null or exists(
    select 1 from public.invoices where visit_id = p_visit_id and voided_at is null and paid_status = 'Lunas'
  )) then
    if exists(select 1 from public.invoices where visit_id = p_visit_id and voided_at is null) then
      raise exception 'ADMISSION_INVALID: tagihan kunjungan ini belum lunas; lunasi atau batalkan tagihan terlebih dahulu sebelum masuk rawat inap';
    end if;
    raise exception 'ADMISSION_INVALID: kunjungan belum selesai; masukkan rawat inap langsung dari kunjungan ini';
  end if;
  select * into v_medical from public.medical_records where visit_id = p_visit_id
    order by created_at desc, id desc limit 1;
  if v_medical.id is null or v_visit.doctor_id is null then
    raise exception 'ADMISSION_INVALID: selesaikan pemeriksaan dan pilih dokter terlebih dahulu'; end if;

  if exists(select 1 from public.inpatient_records r join public.visits v on v.id = r.visit_id
            where v.pet_id = v_visit.pet_id and r.discharged_at is null) then
    raise exception 'ADMISSION_INVALID: pasien sudah memiliki rawat inap aktif'; end if;

  -- A continuation that is still open (not admitted, not billed) is reused.
  select v.id into v_new_visit from public.visits v
  where v.continued_from_visit_id = p_visit_id and v.status <> 'Selesai' and v.checked_out_at is null
    and not exists(select 1 from public.invoices i where i.visit_id = v.id and i.voided_at is null)
    and not exists(select 1 from public.inpatient_records r where r.visit_id = v.id)
  order by v.created_at desc, v.id desc limit 1;
  if v_new_visit is not null then return v_new_visit; end if;

  insert into public.visits(branch_id, customer_id, pet_id, poli, dokter, doctor_id, keluhan, status, source,
    checked_in_at, service_started_at, service_finished_at, continued_from_visit_id)
  values (v_visit.branch_id, v_visit.customer_id, v_visit.pet_id, v_visit.poli, v_visit.dokter, v_visit.doctor_id,
    'Lanjutan rawat inap dari kunjungan ' || to_char(v_visit.created_at at time zone 'Asia/Jakarta', 'DD-MM-YYYY'),
    'Pembayaran', 'walk_in', v_now, v_now, v_now, p_visit_id)
  returning id into v_new_visit;

  -- Clinical findings carry over for continuity; prescriptions and billing do not.
  insert into public.medical_records(visit_id, anamnesis, diagnosis, therapy, suhu, berat, gejala_klinis,
    hasil_penunjang, penunjang_urls, continued_from_record_id, submission_key, submission_hash, submitted_by)
  values (v_new_visit, v_medical.anamnesis, v_medical.diagnosis, v_medical.therapy, v_medical.suhu, v_medical.berat,
    v_medical.gejala_klinis, v_medical.hasil_penunjang, v_medical.penunjang_urls, v_medical.id, v_submission,
    md5(jsonb_build_object('visit', p_visit_id, 'actor', auth.uid())::text), auth.uid());
  return v_new_visit;
end $$;
revoke all on function public.clinic_continue_visit_to_inpatient(uuid, text) from public, anon, service_role;
grant execute on function public.clinic_continue_visit_to_inpatient(uuid, text) to authenticated;

-- K14 (keputusan owner 29 Okt): pet hotel (sehat) berbeda dari rawat inap sakit.
--
-- (a) Check-in pet hotel TIDAK mewajibkan pemeriksaan dokter selesai, dokter pada kunjungan,
--     maupun persetujuan khusus Rawat Inap: paramedis/staf klinik bisa check-in. Belum ada jenis
--     formulir persetujuan khusus pet hotel, jadi tidak ada formulir yang diwajibkan.
--     Kunjungan yang belum diperiksa dibuatkan rekam medis ringkas (tanpa diagnosis) supaya
--     biaya menginap punya tempat, lalu kunjungan pindah ke tahap Pembayaran (sama seperti
--     rawat inap sakit setelah pemeriksaan). Rawat inap sakit: semua syarat lama tetap.
--     Aturan K08 (20261101140000) juga berlaku: tagihan aktif menutup jalur check-in langsung.
-- (b) Tarif harian terpisah: biaya otomatis saat pulang memakai jasa berkategori 'Pet Hotel'
--     untuk periode pet hotel (diatur di master SKU seperti jasa Rawat Inap). Bila tarif pet
--     hotel belum diisi (jasanya tidak ada atau harganya 0), tarif Rawat Inap dipakai dan baris
--     tagihan diberi catatan peringatan. Satu jasa 'Pet Hotel' disiapkan dengan harga 0
--     (= belum diatur) bila belum ada; harga tidak dikarang.
-- Signature, SECURITY DEFINER, search_path dan grant semua fungsi sama; peran sesi dibaca lewat
-- auth.role() (perbaikan 20261031095000). Idempoten: aman dijalankan ulang.

-- 1. Kategori tindakan baru untuk jasa tarif pet hotel.
do $$
declare v_name text;
begin
  for v_name in
    select c.conname from pg_constraint c
    where c.conrelid = 'public.items'::regclass and c.contype = 'c'
      and pg_get_constraintdef(c.oid) like '%tindakan_kategori%'
  loop
    execute format('alter table public.items drop constraint %I', v_name);
  end loop;
end $$;
alter table public.items add constraint items_tindakan_kategori_check
  check (tindakan_kategori in ('Konsultasi', 'Vaksinasi', 'Operasi', 'Grooming', 'Rawat Inap', 'Lab', 'Pet Hotel'));

-- 2. Jasa tarif pet hotel. Harga 0 = belum diatur; owner/admin mengisi tarifnya di master SKU.
insert into public.items(code, name, unit, item_type, is_active, tindakan_kategori, sell_price, category_id)
select 'JASA-PET-HOTEL', 'Pet Hotel (per hari)', 'hari', 'Jasa', true, 'Pet Hotel', 0,
  (select i.category_id from public.items i where i.tindakan_kategori = 'Rawat Inap' and i.is_active
   order by i.name, i.id limit 1)
where not exists (select 1 from public.items where tindakan_kategori = 'Pet Hotel')
on conflict (code) do nothing;

-- 3. Penjaga petugas rawat inap: sama dengan 20261006090000, kecuali check-in pet hotel tidak
--    mengikat dokter PJ (tidak butuh dokter pada kunjungan).
create or replace function public.protect_inpatient_care_staff() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_record public.inpatient_records%rowtype;v_visit public.visits%rowtype;
begin
 if coalesce(auth.role(),'')<>'authenticated' or auth.uid() is null then
   raise exception using errcode='P0001',message='ACCESS_DENIED: pengguna tidak terautentikasi';
 end if;
 perform 1 from public.profiles where id=auth.uid() and is_active=true for share;
 if not found then raise exception using errcode='P0001',message='ACCESS_DENIED: pengguna tidak aktif';end if;
 if tg_table_name='inpatient_records' then
   if not public.user_can_access_branch(new.branch_id) then
     raise exception using errcode='P0001',message='ACCESS_DENIED: cabang tidak dapat diakses';
   end if;
   if tg_op='UPDATE' then
     if new.doctor_id is distinct from old.doctor_id or new.doctor_name is distinct from old.doctor_name
       or new.visit_id is distinct from old.visit_id or new.branch_id is distinct from old.branch_id then
       raise exception using errcode='P0001',message='CARE_INVALID: dokter PJ awal tetap tersimpan';
     end if;
   else
     select * into v_visit from public.visits where id=new.visit_id for share;
     if not found or v_visit.branch_id is distinct from new.branch_id then
       raise exception using errcode='P0001',message='CARE_INVALID: pilih dokter PJ pada kunjungan sebelum masuk rawat inap';
     end if;
     -- K14: a pet hotel guest is healthy boarding checked in by staff; no PIC doctor is bound.
     if new.stay_type='pet_hotel' then
       new.doctor_id:=null;
       new.doctor_name:=null;
       return new;
     end if;
     if v_visit.doctor_id is null then
       raise exception using errcode='P0001',message='CARE_INVALID: pilih dokter PJ pada kunjungan sebelum masuk rawat inap';
     end if;
     new.doctor_id:=v_visit.doctor_id;
     new.doctor_name:=public.clinic_staff_name(new.doctor_id,new.branch_id,'doctor');
   end if;
   return new;
 end if;
 select * into v_record from public.inpatient_records where id=new.inpatient_record_id for update;
 if not found or not public.user_can_access_branch(v_record.branch_id) then
   raise exception using errcode='P0001',message='ACCESS_DENIED: rawat inap tidak dapat diakses';
 end if;
 if v_record.discharged_at is not null then
   raise exception using errcode='P0001',message='CARE_INVALID: rawat inap sudah ditutup';
 end if;
 if nullif(btrim(new.condition_note),'') is null then
   raise exception using errcode='P0001',message='CARE_INVALID: kondisi pasien wajib diisi';
 end if;
 if tg_op='UPDATE' then
   if new.inpatient_record_id is distinct from old.inpatient_record_id then
     raise exception using errcode='P0001',message='CARE_INVALID: catatan tidak dapat dipindahkan ke pasien lain';
   end if;
   new.updated_at:=now();new.updated_by:=auth.uid();new.created_by:=old.created_by;
 else new.created_by:=auth.uid();
 end if;
 if new.log_kind is null then
   if tg_op<>'UPDATE' or old.log_kind is not null
     or new.visit_doctor_id is not null or new.paramedic_id is not null then
     raise exception using errcode='P0001',message='CARE_INVALID: pilih jenis laporan pemantauan atau visit dokter';
   end if;
   new.doctor_name:=old.doctor_name;new.paramedic_name:=old.paramedic_name;
   return new;
 end if;
 if new.log_kind='doctor_visit' and new.visit_doctor_id is null then
   raise exception using errcode='P0001',message='CARE_INVALID: dokter visit wajib dipilih';
 end if;
 if new.visit_doctor_id is null then new.doctor_name:=null;
 elsif tg_op='UPDATE' and new.visit_doctor_id is not distinct from old.visit_doctor_id
   and new.log_kind is not distinct from old.log_kind then new.doctor_name:=old.doctor_name;
 else new.doctor_name:=public.clinic_staff_name(new.visit_doctor_id,v_record.branch_id,'doctor');end if;
 if new.paramedic_id is null then new.paramedic_name:=null;
 elsif tg_op='UPDATE' and new.paramedic_id is not distinct from old.paramedic_id then new.paramedic_name:=old.paramedic_name;
 else new.paramedic_name:=public.clinic_staff_name(new.paramedic_id,v_record.branch_id,'paramedic');end if;
 return new;
end;
$$;
revoke all on function public.protect_inpatient_care_staff() from public,anon,authenticated,service_role;

-- 4. Masuk rawat inap bertipe. 'sakit': tetap lewat clinic_admit_inpatient (dokter, pemeriksaan,
--    persetujuan, K08). 'pet_hotel': check-in sendiri tanpa dokter/pemeriksaan/persetujuan.
create or replace function public.clinic_admit_inpatient_typed(
  p_visit_id uuid, p_treatment_plan text, p_request_key text, p_stay_type text
) returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_key text := nullif(btrim(p_request_key), '');
  v_plan text := nullif(btrim(p_treatment_plan), '');
  v_visit public.visits%rowtype;
  v_prior public.inpatient_records%rowtype;
  v_id uuid;
  v_stored text;
  v_hash text;
  v_legacy_hash text;
  v_medical uuid;
  v_now timestamptz := now();
begin
  if coalesce(auth.role(), '') <> 'authenticated' or auth.uid() is null then
    raise exception 'ACCESS_DENIED: pengguna tidak aktif atau tidak terautentikasi'; end if;
  if not public.inpatient_clinic_module_access() then
    raise exception 'ACCESS_DENIED: peran ini tidak memiliki akses modul klinik'; end if;
  if p_stay_type is null or p_stay_type not in ('sakit', 'pet_hotel') then
    raise exception 'ADMISSION_INVALID: pilih tipe rawat inap'; end if;
  if v_key is null or length(v_key) > 100 then
    raise exception 'ADMISSION_INVALID: isi rencana tindakan dan muat ulang formulir'; end if;
  -- Same-key retries are serialized before anything is read, whatever visit they name.
  perform pg_advisory_xact_lock(hashtextextended('inpatient-admission:' || v_key, 0));
  -- Visit then pet: same order as the base RPC and the per-patient guard.
  select * into v_visit from public.visits where id = p_visit_id for update;
  if not found or not public.user_can_access_branch(v_visit.branch_id) then
    raise exception 'ACCESS_DENIED: kunjungan atau cabang tidak dapat diakses'; end if;
  perform 1 from public.pets where id = v_visit.pet_id for no key update;

  select * into v_prior from public.inpatient_records where admission_request_key = v_key for update;

  if p_stay_type = 'sakit' then
    v_id := public.clinic_admit_inpatient(p_visit_id, p_treatment_plan, p_request_key);
    if v_prior.id is not null then
      if v_prior.stay_type is distinct from p_stay_type then
        raise exception 'IDEMPOTENCY_CONFLICT: kunci masuk rawat inap dipakai untuk data berbeda'; end if;
      return v_id;
    end if;
    select stay_type into v_stored from public.inpatient_records where id = v_id;
    if v_stored is distinct from p_stay_type then
      raise exception 'IDEMPOTENCY_CONFLICT: kunci masuk rawat inap dipakai untuk data berbeda'; end if;
    return v_id;
  end if;

  -- K14 pet hotel check-in.
  if v_plan is null or length(v_plan) > 4000 then
    raise exception 'ADMISSION_INVALID: isi catatan penitipan dan muat ulang formulir'; end if;
  v_hash := md5(jsonb_build_object('visit', p_visit_id, 'plan', v_plan, 'actor', auth.uid(), 'stay', 'pet_hotel')::text);
  -- Stays checked in before this migration were written by the base RPC (its hash format).
  v_legacy_hash := md5(jsonb_build_object('visit', p_visit_id, 'plan', v_plan, 'actor', auth.uid())::text);
  if v_prior.id is not null then
    if v_prior.stay_type is distinct from 'pet_hotel'
       or v_prior.admission_request_hash not in (v_hash, v_legacy_hash) then
      raise exception 'IDEMPOTENCY_CONFLICT: kunci masuk rawat inap dipakai untuk data berbeda'; end if;
    return v_prior.id;
  end if;
  if exists(select 1 from public.inpatient_records where visit_id = p_visit_id and discharged_at is null) then
    raise exception 'ADMISSION_INVALID: pasien sudah memiliki rawat inap aktif'; end if;
  if v_visit.checked_out_at is not null or v_visit.status = 'Selesai' then
    raise exception 'ADMISSION_INVALID: kunjungan sudah selesai; daftarkan kunjungan baru untuk pet hotel'; end if;
  -- K08: an active invoice closes the direct path for pet hotel too.
  if exists(select 1 from public.invoices where visit_id = p_visit_id and voided_at is null and paid_status = 'Lunas') then
    raise exception 'ADMISSION_INVALID: tagihan kunjungan ini sudah lunas; gunakan Lanjutkan ke Rawat Inap'; end if;
  if exists(select 1 from public.invoices where visit_id = p_visit_id and voided_at is null) then
    raise exception 'ADMISSION_INVALID: tagihan kunjungan ini belum lunas; lunasi atau batalkan tagihan terlebih dahulu sebelum masuk rawat inap'; end if;

  -- No doctor examination is required. A visit that was never examined gets a short record so
  -- the boarding fee has a billing home; it carries no diagnosis and is locked like a posted record.
  select id into v_medical from public.medical_records where visit_id = p_visit_id
    order by created_at desc, id desc limit 1;
  if v_medical is null then
    insert into public.medical_records(visit_id, anamnesis, submission_key, submission_hash, submitted_by)
    values (p_visit_id, 'Check-in pet hotel (hewan sehat), tanpa pemeriksaan dokter',
      'k14-pet-hotel:' || v_key, v_hash, auth.uid())
    returning id into v_medical;
  end if;
  if v_visit.status in ('Menunggu', 'Diperiksa') then
    update public.visits set status = 'Pembayaran', called_at = coalesce(called_at, v_now),
      service_started_at = coalesce(service_started_at, v_now),
      service_finished_at = coalesce(service_finished_at, v_now)
    where id = p_visit_id;
    insert into public.visit_operational_events(visit_id, branch_id, event_type, payload, created_by)
    values (p_visit_id, v_visit.branch_id, 'service_finished', jsonb_build_object('source', 'pet_hotel_check_in'), auth.uid());
  end if;

  insert into public.inpatient_records(branch_id, visit_id, medical_record_id, treatment_plan, created_by,
    admission_request_key, admission_request_hash, stay_type)
  values (v_visit.branch_id, p_visit_id, v_medical, v_plan, auth.uid(), v_key, v_hash, 'pet_hotel')
  returning id into v_id;
  insert into public.inpatient_status_log(inpatient_record_id, previous_status, new_status, changed_by, notes)
  values (v_id, null, 'stabil', auth.uid(), 'Check-in pet hotel');
  return v_id;
end $$;
revoke all on function public.clinic_admit_inpatient_typed(uuid, text, text, text) from public, anon, service_role;
grant execute on function public.clinic_admit_inpatient_typed(uuid, text, text, text) to authenticated;

-- 5. Pemulangan: sama dengan 20261030110000 (K08 semua periode, hari yang sudah ditagih tidak
--    ditagih dua kali), tetapi hari dihitung per tarif: periode 'sakit' memakai jasa Rawat Inap,
--    periode 'pet_hotel' memakai jasa Pet Hotel (fallback tarif Rawat Inap + catatan peringatan).
create or replace function public.clinic_change_inpatient_condition(
  p_inpatient_id uuid, p_new_status text, p_notes text
) returns boolean language plpgsql security definer set search_path = '' as $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_record public.inpatient_records%rowtype;
  v_sick public.items%rowtype;
  v_hotel public.items%rowtype;
  v_group record;
  v_medical_record_id uuid;
  v_days integer;
  v_total_days integer;
  v_billed_days numeric;
  v_periods integer;
  v_sick_periods integer;
  v_hotel_periods integer;
  v_price numeric;
  v_name text;
  v_unit text;
  v_kategori text;
  v_label text;
  v_warning text;
  v_discharged_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'authenticated'
     or v_user is null then
    raise exception using errcode='P0001', message='ACCESS_DENIED: pengguna tidak terautentikasi';
  end if;
  if p_new_status not in ('stabil','kritis','sembuh','rip','pulang_paksa') then
    raise exception using errcode='P0001', message='LOG_INVALID: status rawat inap tidak valid';
  end if;
  select * into v_record from public.inpatient_records
  where id = p_inpatient_id for update;
  if not found or not public.user_can_access_branch(v_record.branch_id) then
    raise exception using errcode='P0001', message='ACCESS_DENIED: rawat inap tidak dapat diakses';
  end if;
  if not exists(select 1 from public.visits v where v.id=v_record.visit_id
    and v.branch_id=v_record.branch_id) then
    raise exception using errcode='P0001', message='ACCESS_DENIED: cabang kunjungan tidak cocok'; end if;
  select role into v_role from public.profiles where id = v_user;
  if v_role is null or (p_new_status = 'rip' and v_role <> 'DOCTOR') then
    raise exception using errcode='P0001', message='ACCESS_DENIED: status RIP hanya boleh diubah dokter';
  end if;
  if v_record.condition_status = p_new_status then return false; end if;
  if v_record.condition_status = 'pulang_paksa' then
    raise exception using errcode='P0001', message='INPATIENT_CLOSED: pasien sudah keluar';
  end if;
  if p_new_status = 'pulang_paksa' then
    if v_record.discharged_at is not null then
      raise exception using errcode='P0001', message='INPATIENT_CLOSED: pasien sudah keluar';
    end if;
    -- A distinct Owner/Admin-managed form is required. The signed snapshot and
    -- admission time are both retained; an older admission form cannot qualify.
    if not exists (
      select 1 from public.consents c
      join public.consent_templates t on t.id = c.template_id
      where c.visit_id = v_record.visit_id
        and c.consent_branch_id = v_record.branch_id
        and c.status = 'sudah_ttd' and c.kategori = 'Pulang Paksa'
        and nullif(btrim(c.signer_name), '') is not null
        and nullif(btrim(c.signature_data), '') is not null
        and c.signed_at >= v_record.admitted_at
        and t.kategori = 'Pulang Paksa' and t.is_active
        and (t.branch_id is null or t.branch_id = v_record.branch_id)
    ) then
      raise exception using errcode='P0001', message='CONSENT_REQUIRED: tandatangani form Pulang Paksa yang berlaku untuk cabang pasien';
    end if;
  end if;

  v_discharged_at := case when p_new_status in ('sembuh','rip','pulang_paksa') then now() else null end;
  if v_discharged_at is not null and exists(select 1 from public.invoices
      where visit_id=v_record.visit_id and voided_at is null) then
    raise exception using errcode='P0001', message='INVOICE_EXISTS: tagihan sudah terbit sebelum biaya rawat inap dihitung';
  end if;
  -- K08: reopening a discharged stay. With an active invoice the stay could never be
  -- discharged again (INVOICE_EXISTS) nor invoiced (INPATIENT_OPEN); use a continuation.
  if v_discharged_at is null and v_record.discharged_at is not null then
    if exists(select 1 from public.invoices
        where visit_id=v_record.visit_id and voided_at is null) then
      raise exception using errcode='P0001', message='INVOICE_EXISTS: tagihan sudah terbit; rawat inap yang sudah pulang tidak dapat dibuka lagi pada kunjungan ini';
    end if;
    if exists(select 1 from public.inpatient_records r
        join public.visits v on v.id = r.visit_id
        where v.pet_id = (select pet_id from public.visits where id = v_record.visit_id)
          and r.discharged_at is null and r.id <> p_inpatient_id) then
      raise exception using errcode='P0001', message='ADMISSION_INVALID: pasien sudah memiliki rawat inap aktif';
    end if;
  end if;
  insert into public.inpatient_status_log(
    inpatient_record_id, previous_status, new_status, changed_by, notes
  ) values (p_inpatient_id, v_record.condition_status, p_new_status, v_user, p_notes);
  update public.inpatient_records set condition_status=p_new_status,
    discharged_at=v_discharged_at where id=p_inpatient_id;

  if v_discharged_at is not null then
    select * into v_sick from public.items
    where tindakan_kategori='Rawat Inap' and is_active
    order by name, id limit 1;
    -- K14: separate daily tariff for pet hotel periods.
    select * into v_hotel from public.items
    where tindakan_kategori='Pet Hotel' and is_active
    order by name, id limit 1;
    select m.id into v_medical_record_id from public.medical_records m
    where m.visit_id = v_record.visit_id
    order by m.created_at desc, m.id desc limit 1;
    if v_medical_record_id is not null then
      -- Never-billed automatic fee lines of both tariffs are recalculated below (also a line
      -- written before K14 with the Rawat Inap tariff for a pet hotel period).
      delete from public.prescription_items p
      using public.medical_records m
      where m.id = p.medical_record_id and m.visit_id = v_record.visit_id
        and p.item_id in (v_sick.id, v_hotel.id)
        and not exists(select 1 from public.invoice_items ii where ii.prescription_item_id = p.id);
      -- One fee line per tariff item. Without a Pet Hotel service both stay types share the
      -- Rawat Inap item, so their days are counted (and deducted) together as before K14.
      for v_group in
        select g.item_id, array_agg(g.stay_type) as stay_types
        from (values ('sakit'::text, v_sick.id), ('pet_hotel'::text, coalesce(v_hotel.id, v_sick.id))) g(stay_type, item_id)
        where g.item_id is not null
        group by g.item_id
      loop
        -- K08: every discharged period of this visit, each rounded up per 24 hours (min 1).
        select count(*), coalesce(sum(greatest(1, ceil(extract(epoch from
            (r.discharged_at - r.admitted_at)) / 86400)::integer)), 0),
          count(*) filter (where r.stay_type = 'sakit'), count(*) filter (where r.stay_type = 'pet_hotel')
          into v_periods, v_total_days, v_sick_periods, v_hotel_periods
        from public.inpatient_records r
        where r.visit_id = v_record.visit_id and r.discharged_at is not null
          and r.stay_type = any(v_group.stay_types);
        continue when v_periods = 0;
        -- Days already billed: fee lines on an active invoice, plus fee lines on the billing
        -- record that an older invoice still references (kept, and shown again at checkout).
        select coalesce(sum(p.qty), 0) into v_billed_days
        from public.prescription_items p
        join public.medical_records m on m.id = p.medical_record_id
        where m.visit_id = v_record.visit_id and p.item_id = v_group.item_id
          and (exists(select 1 from public.invoice_items ii
                 join public.invoices i on i.id = ii.invoice_id
                 where ii.prescription_item_id = p.id and i.voided_at is null)
               or (p.medical_record_id = v_medical_record_id and exists(
                 select 1 from public.invoice_items ii where ii.prescription_item_id = p.id)));
        v_days := v_total_days - ceil(v_billed_days)::integer;
        continue when v_days <= 0;

        v_warning := '';
        if v_group.item_id = v_hotel.id then
          v_name := v_hotel.name;
          v_unit := coalesce(v_hotel.unit, 'hari');
          if coalesce(v_hotel.sell_price, 0) > 0 then
            v_price := v_hotel.sell_price;
          else
            v_price := coalesce(v_sick.sell_price, 0);
            v_warning := '; tarif Pet Hotel belum diatur, memakai tarif Rawat Inap';
          end if;
        else
          v_name := v_sick.name;
          v_unit := coalesce(v_sick.unit, 'hari');
          v_price := coalesce(v_sick.sell_price, 0);
          if v_hotel_periods > 0 then
            v_warning := '; tarif Pet Hotel belum diatur, memakai tarif Rawat Inap';
          end if;
        end if;
        -- Rawat Inap stays keep their consent-bearing category; pure pet hotel lines do not.
        v_kategori := case when v_sick_periods > 0 then 'Rawat Inap' else 'Pet Hotel' end;
        v_label := case when v_sick_periods > 0 then 'rawat inap' else 'pet hotel' end;
        insert into public.prescription_items(
          medical_record_id, item_id, nama_obat, qty, harga, satuan,
          jenis, kategori, aturan_pakai
        ) values (
          v_medical_record_id, v_group.item_id, v_name, v_days,
          v_price, v_unit,
          'jasa', v_kategori,
          'Otomatis dari lama ' || v_label || ': ' || v_days || ' hari'
            || case when v_periods > 1 or v_billed_days > 0 then
                 ' (total ' || v_total_days || ' hari dari ' || v_periods || ' periode'
                 || case when v_billed_days > 0 then ', ' || trim_scale(v_billed_days)::text || ' hari sudah ditagih' else '' end
                 || ')'
               else '' end
            || v_warning
        );
      end loop;
    end if;
  end if;
  return true;
end;
$function$;
revoke all on function public.clinic_change_inpatient_condition(uuid,text,text)
  from public, anon, service_role;
grant execute on function public.clinic_change_inpatient_condition(uuid,text,text)
  to authenticated;

-- C05 lanjutan (keputusan pemilik 29 Okt 2026): kode voucher yang ditautkan ke kode kampanye
-- AKTIF tidak boleh lagi diketik langsung. Hanya kode kampanyenya yang berlaku, supaya batas
-- pemakaian dan laporan kampanye tidak bisa dilewati dengan mengetik kode voucher aslinya.
--
--   * Berlaku di semua jalur yang menulis voucher ke dokumen: struk POS (/kasir), invoice klinik
--     per kunjungan, dan pembayaran rombongan klinik (semuanya lewat INSERT sales/invoices,
--     termasuk clinic_post_invoice, sehingga trigger C05 yang sudah ada cukup diperluas).
--   * Voucher yang tidak tertaut ke kampanye mana pun, atau hanya ke kampanye yang dinonaktifkan,
--     tetap bisa dipakai seperti biasa.
--   * Dokumen lama tidak disentuh: koreksi/terbit ulang yang mempertahankan voucher yang sama
--     tetap lolos. Yang ditolak hanya dokumen baru, atau perubahan yang MEMASANG voucher
--     tertaut tanpa kode kampanyenya.
--
-- Idempoten: create or replace saja; trigger yang ada (c05_sale_campaign_code,
-- c05_invoice_campaign_code) sudah memanggil fungsi ini.

create or replace function public.voucher_wajib_lewat_kampanye(p_voucher_code text) returns boolean
language sql stable security definer set search_path = '' as $$
  select p_voucher_code is not null and exists (
    select 1 from public.campaign_codes c
    join public.vouchers v on v.id = c.voucher_id
    where c.is_active and upper(v.code) = upper(btrim(p_voucher_code))
  )
$$;
revoke all on function public.voucher_wajib_lewat_kampanye(text) from public, anon, authenticated, service_role;
comment on function public.voucher_wajib_lewat_kampanye(text) is
  'C05: true bila voucher tertaut ke kode kampanye aktif, sehingga hanya boleh dipakai lewat kode kampanyenya.';

create or replace function public.guard_campaign_code_use() returns trigger
language plpgsql security definer set search_path = '' as $$
declare k public.campaign_codes%rowtype; v_voucher text; v_used bigint; src_id uuid; src_code text; src_voucher text;
begin
  if tg_op = 'UPDATE' then
    if new.campaign_code is distinct from old.campaign_code then
      raise exception 'KODE_KAMPANYE: Kode kampanye pada dokumen tidak boleh diubah' using errcode = '23514';
    end if;
    if new.campaign_code is not null and new.voucher_code is distinct from old.voucher_code then
      raise exception 'KODE_KAMPANYE: Voucher dari kode kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    -- Memasang voucher tertaut kampanye lewat koreksi sama saja dengan mengetiknya langsung.
    if new.campaign_code is null and new.voucher_code is distinct from old.voucher_code
       and public.voucher_wajib_lewat_kampanye(new.voucher_code) then
      raise exception 'KODE_KAMPANYE: Voucher ini hanya bisa dipakai lewat kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  -- Clinic void+reissue: the new invoice inherits the original code and its single use.
  if tg_table_name = 'invoices' then
    src_id := (to_jsonb(new) ->> 'reissued_from')::uuid;   -- sales rows have no such column
  end if;
  if src_id is not null then
    select i.campaign_code, i.voucher_code into src_code, src_voucher
      from public.invoices i where i.id = src_id;
    if new.campaign_code is null then new.campaign_code := src_code; end if;
    if new.campaign_code is distinct from src_code then
      raise exception 'KODE_KAMPANYE: Penerbitan ulang tidak boleh mengganti kode kampanye' using errcode = '23514';
    end if;
    if src_code is not null and new.voucher_code is distinct from src_voucher then
      raise exception 'KODE_KAMPANYE: Voucher dari kode kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    -- Terbit ulang yang mempertahankan voucher lama tetap lolos; mengganti ke voucher tertaut tidak.
    if new.campaign_code is null and new.voucher_code is distinct from src_voucher
       and public.voucher_wajib_lewat_kampanye(new.voucher_code) then
      raise exception 'KODE_KAMPANYE: Voucher ini hanya bisa dipakai lewat kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.campaign_code is null then
    if public.voucher_wajib_lewat_kampanye(new.voucher_code) then
      raise exception 'KODE_KAMPANYE: Voucher ini hanya bisa dipakai lewat kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  -- Row lock serializes every checkout of this code until its transaction ends.
  select * into k from public.campaign_codes c where c.code = new.campaign_code for update;
  if not found then
    raise exception 'KODE_KAMPANYE: Kode % tidak ditemukan', new.campaign_code using errcode = 'P0001';
  end if;
  if not k.is_active then
    raise exception 'KODE_KAMPANYE: Kode % sedang dinonaktifkan', k.code using errcode = 'P0001';
  end if;
  if k.voucher_id is not null then
    select v.code into v_voucher from public.vouchers v where v.id = k.voucher_id;
    if new.voucher_code is distinct from v_voucher then
      raise exception 'KODE_KAMPANYE: Kode % harus memakai voucher %', k.code, v_voucher using errcode = '23514';
    end if;
  elsif new.voucher_code is not null then
    raise exception 'KODE_KAMPANYE: Kode promo % tidak bisa digabung dengan voucher', k.code using errcode = '23514';
  end if;
  if k.max_uses is not null then
    v_used := public.campaign_code_used(k.code);
    if v_used >= k.max_uses then
      raise exception 'KODE_KAMPANYE: Kode % sudah mencapai batas pemakaian (% kali)', k.code, k.max_uses
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.guard_campaign_code_use() from public, anon, authenticated, service_role;

-- I09 lanjutan (keputusan pemilik 29 Okt 2026): riwayat per SKU induk racikan nonstok.
--
-- Seperti kartu stok, tetapi virtual: induk racikan tidak pernah punya stok fisik, jadi
-- riwayatnya disusun dari fakta yang sudah ada, tanpa menulis apa pun:
--   * "Masuk"  = setiap racikan yang dibuat untuk SKU ini (clinic_compound_sales.sale_item_id
--                -> compounding_recipes), 1 racikan per baris;
--   * "Keluar" = setiap baris invoice klinik yang menagih racikan tersebut
--                (invoice_items.compound_recipe_id).
-- Tidak ada harga/HPP yang dikembalikan (konvensi read_compound_trace, PR #281).
--
-- Akses: pengguna aktif dengan modul Persediaan atau Klinik (aturan bawaan sama dengan
-- lib/akses.ts bila peran belum punya aturan tersimpan). Baris dari cabang yang tidak bisa
-- diakses tetap ikut dihitung dan nomornya tetap tampil, tetapi tanpa id tautan, tanpa nama
-- pasien/pelanggan, dan tanpa nama racikan.
--
-- Paging: p_offset/p_limit dengan total_baris di setiap baris, dibaca lengkap oleh aplikasi
-- dengan verifikasi jumlah (readCompleteList), sama seperti kartu stok.

create index if not exists clinic_compound_sales_sale_item_idx
  on public.clinic_compound_sales (sale_item_id) where recipe_id is not null;

create or replace function public.read_compound_parent_history(
  p_item_id uuid, p_dari date, p_sampai date, p_offset integer default 0, p_limit integer default 500
) returns table (
  id text, arah text, waktu timestamptz, tanggal date, qty numeric, satuan text,
  nomor_racikan text, recipe_id uuid, nama_racikan text, status_racikan text, sumber text,
  visit_id uuid, pasien text, pelanggan text, cabang text,
  invoice_id uuid, nomor_invoice text, invoice_batal boolean,
  bisa_dibuka boolean, total_baris bigint
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare me public.profiles%rowtype;
begin
  if p_item_id is null or auth.uid() is null or coalesce(auth.role(), '') <> 'authenticated' then
    raise exception 'Akses riwayat racikan ditolak' using errcode = '42501';
  end if;
  select * into me from public.profiles p where p.id = auth.uid() and p.is_active;
  if not found or not (me.role = 'OWNER'
    or exists (select 1 from public.role_modules m where m.role = me.role and m.module_id in ('pos', 'klinik'))
    or (not exists (select 1 from public.role_modules m where m.role = me.role) and me.role in ('ADMIN', 'DOCTOR', 'STAFF'))) then
    raise exception 'Akses riwayat racikan ditolak' using errcode = '42501';
  end if;
  if p_dari is null or p_sampai is null or p_dari > p_sampai
     or p_offset is null or p_offset < 0 or p_limit is null or p_limit not between 1 and 1000 then
    raise exception 'RIWAYAT_TIDAK_VALID: rentang tanggal atau halaman tidak valid' using errcode = '22023';
  end if;
  if not exists (select 1 from public.items i where i.id = p_item_id)
     or not (clinic_private.is_racikan_sku(p_item_id)
             or exists (select 1 from public.clinic_compound_sales s where s.sale_item_id = p_item_id)) then
    raise exception 'RIWAYAT_TIDAK_VALID: barang ini bukan induk racikan' using errcode = '22023';
  end if;

  return query
  with racikan as (
    select r.id rid, r.recipe_name::text recipe_name, r.status::text status, r.created_at, s.sale_unit,
           v.id vid, v.branch_id, v.created_at visit_at, b.name::text branch_name,
           pt.name::text pet_name, c.name::text customer_name,
           fv.name::text formula_name, fv.version formula_version,
           public.user_can_access_branch(v.branch_id) boleh
    from public.clinic_compound_sales s
    join public.compounding_recipes r on r.id = s.recipe_id
    join public.visits v on v.id = s.visit_id
    left join public.branches b on b.id = v.branch_id
    left join public.pets pt on pt.id = v.pet_id
    left join public.customers c on c.id = v.customer_id
    left join public.compound_official_usage u on u.recipe_id = r.id
    left join public.compound_formula_versions fv on fv.id = u.formula_version_id
    where s.sale_item_id = p_item_id and s.recipe_id is not null
  ),
  -- Nomor racikan = nomor resep di halaman racik (R/<tahun>/<bulan-hari>/<3 huruf id>, UTC).
  bernomor as (
    select k.*, 'R/' || to_char(k.visit_at at time zone 'UTC', 'YYYY') || '/' || to_char(k.visit_at at time zone 'UTC', 'MMDD')
           || '/' || upper(left(k.rid::text, 3)) nomor
    from racikan k
  ),
  baris as (
    select 'masuk:' || k.rid::text id, 'masuk'::text arah, k.created_at waktu,
           (k.created_at at time zone 'Asia/Jakarta')::date tanggal, 1::numeric qty, k.sale_unit::text satuan,
           k.nomor, k.rid, k.recipe_name, k.status, k.formula_name, k.formula_version,
           k.vid, k.pet_name, k.customer_name, k.branch_name,
           null::uuid inv_id, null::text inv_no, null::boolean inv_void, k.boleh
    from bernomor k
    union all
    select 'keluar:' || ii.id::text, 'keluar', inv.created_at,
           (inv.created_at at time zone 'Asia/Jakarta')::date, ii.qty::numeric, coalesce(ii.satuan, k.sale_unit)::text,
           k.nomor, k.rid, k.recipe_name, k.status, k.formula_name, k.formula_version,
           k.vid, k.pet_name, k.customer_name, k.branch_name,
           inv.id, inv.invoice_no::text, inv.voided_at is not null, k.boleh
    from bernomor k
    join public.invoice_items ii on ii.compound_recipe_id = k.rid
    join public.invoices inv on inv.id = ii.invoice_id
  ),
  terpilih as (
    select x.*, count(*) over () jumlah from baris x where x.tanggal between p_dari and p_sampai
  )
  select t.id, t.arah, t.waktu, t.tanggal, t.qty, t.satuan,
         t.nomor, case when t.boleh then t.rid end,
         case when t.boleh then t.recipe_name end, t.status,
         case when t.formula_name is not null then 'Resep resmi: ' || t.formula_name || ' v' || t.formula_version
              else 'Racikan bebas dari rekam medis' end,
         case when t.boleh then t.vid end,
         case when t.boleh then t.pet_name end, case when t.boleh then t.customer_name end, t.branch_name,
         case when t.boleh then t.inv_id end, t.inv_no, t.inv_void,
         t.boleh, t.jumlah
  from terpilih t
  order by t.waktu, t.id
  offset p_offset limit p_limit;
end $$;
revoke all on function public.read_compound_parent_history(uuid, date, date, integer, integer) from public, anon, service_role;
grant execute on function public.read_compound_parent_history(uuid, date, date, integer, integer) to authenticated;
comment on function public.read_compound_parent_history(uuid, date, date, integer, integer) is
  'I09: riwayat virtual SKU induk racikan nonstok (Masuk = racikan dibuat, Keluar = racikan ditagih). Baca saja, tanpa harga.';

-- C05: pembayaran rombongan klinik + voucher yang hanya berlaku lewat kode kampanye.
--
-- Satu kedatangan rombongan = satu pemakaian kode kampanye. Kodenya menempel di SATU nota
-- ("nota pembawa", invoices.campaign_code terisi, dihitung database), sedangkan nota hewan lain
-- ikut menikmati voucher kampanyenya tanpa kode supaya pemakaian tidak terhitung ganda.
-- Aturan 20261101150000 menolak voucher tertaut kampanye aktif tanpa kode kampanye, sehingga
-- nota hewan lain itu ikut tertolak.
--
-- Perbaikan yang bisa diverifikasi database (bukan percaya pada klien):
--   * kolom baru invoices.campaign_carrier_id menunjuk nota pembawa kode;
--   * nota pendamping hanya diterima bila nota pembawanya ada, belum dibatalkan, membawa kode
--     kampanye, memakai voucher yang sama, dan berasal dari rombongan yang sama (pemilik dan
--     cabang sama, kunjungan di hari WIB yang sama, kunjungan berbeda);
--   * nota pendamping tidak membawa campaign_code → tidak menambah hitungan pemakaian;
--   * penanda tidak boleh diubah setelah nota terbit; terbit ulang mewarisinya.
-- Voucher mentah tanpa penanda tetap ditolak seperti sebelumnya.
--
-- clinic_post_invoice ikut menyimpan p_invoice->>'campaign_carrier_id' di INSERT atomiknya
-- (tambalan berjangkar eksak, gagal tertutup bila fungsinya berubah). Idempoten.

alter table public.invoices add column if not exists campaign_carrier_id uuid
  references public.invoices(id) on delete restrict;
create index if not exists invoices_campaign_carrier_idx on public.invoices (campaign_carrier_id)
  where campaign_carrier_id is not null;
comment on column public.invoices.campaign_carrier_id is
  'C05: nota rombongan pembawa kode kampanye; nota ini menikmati voucher kampanyenya tanpa menambah pemakaian.';

create or replace function public.guard_campaign_code_use() returns trigger
language plpgsql security definer set search_path = '' as $$
declare k public.campaign_codes%rowtype; v_voucher text; v_used bigint; src_id uuid; src_code text; src_voucher text;
  src_carrier uuid; v_carrier uuid; old_carrier uuid; c public.invoices%rowtype;
  c_visit public.visits%rowtype; n_visit public.visits%rowtype; ada boolean;
begin
  if tg_table_name = 'invoices' then
    v_carrier := (to_jsonb(new) ->> 'campaign_carrier_id')::uuid;   -- sales rows have no such column
  end if;

  if tg_op = 'UPDATE' then
    if tg_table_name = 'invoices' then
      old_carrier := (to_jsonb(old) ->> 'campaign_carrier_id')::uuid;
      if v_carrier is distinct from old_carrier then
        raise exception 'KODE_KAMPANYE: Penanda nota rombongan kampanye tidak boleh diubah' using errcode = '23514';
      end if;
    end if;
    if new.campaign_code is distinct from old.campaign_code then
      raise exception 'KODE_KAMPANYE: Kode kampanye pada dokumen tidak boleh diubah' using errcode = '23514';
    end if;
    if (new.campaign_code is not null or v_carrier is not null) and new.voucher_code is distinct from old.voucher_code then
      raise exception 'KODE_KAMPANYE: Voucher dari kode kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    -- Memasang voucher tertaut kampanye lewat koreksi sama saja dengan mengetiknya langsung.
    if new.campaign_code is null and new.voucher_code is distinct from old.voucher_code
       and public.voucher_wajib_lewat_kampanye(new.voucher_code) then
      raise exception 'KODE_KAMPANYE: Voucher ini hanya bisa dipakai lewat kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  -- Clinic void+reissue: the new invoice inherits the original code (and group marker) and its single use.
  if tg_table_name = 'invoices' then
    src_id := (to_jsonb(new) ->> 'reissued_from')::uuid;
  end if;
  if src_id is not null then
    select i.campaign_code, i.voucher_code, i.campaign_carrier_id into src_code, src_voucher, src_carrier
      from public.invoices i where i.id = src_id;
    if new.campaign_code is null then new.campaign_code := src_code; end if;
    if v_carrier is null and src_carrier is not null then
      new.campaign_carrier_id := src_carrier; v_carrier := src_carrier;
    end if;
    if new.campaign_code is distinct from src_code then
      raise exception 'KODE_KAMPANYE: Penerbitan ulang tidak boleh mengganti kode kampanye' using errcode = '23514';
    end if;
    if v_carrier is distinct from src_carrier then
      raise exception 'KODE_KAMPANYE: Penanda nota rombongan kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    if (src_code is not null or src_carrier is not null) and new.voucher_code is distinct from src_voucher then
      raise exception 'KODE_KAMPANYE: Voucher dari kode kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    -- Terbit ulang yang mempertahankan voucher lama tetap lolos; mengganti ke voucher tertaut tidak.
    if new.campaign_code is null and new.voucher_code is distinct from src_voucher
       and public.voucher_wajib_lewat_kampanye(new.voucher_code) then
      raise exception 'KODE_KAMPANYE: Voucher ini hanya bisa dipakai lewat kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  -- Nota pendamping rombongan: voucher kampanye lewat nota pembawa kode, tanpa pemakaian tambahan.
  if v_carrier is not null then
    if new.campaign_code is not null then
      raise exception 'KODE_KAMPANYE: Nota pembawa kode tidak boleh sekaligus menjadi nota pendamping' using errcode = '23514';
    end if;
    select * into c from public.invoices i where i.id = v_carrier for share;
    ada := found;
    if ada then
      select * into c_visit from public.visits v where v.id = c.visit_id;
      select * into n_visit from public.visits v where v.id = new.visit_id;
    end if;
    if not ada or c.id = new.id or c.voided_at is not null or c.campaign_code is null
       or new.voucher_code is distinct from c.voucher_code
       or c_visit.id is null or n_visit.id is null or c_visit.id = n_visit.id
       or c_visit.customer_id is null or c_visit.customer_id is distinct from n_visit.customer_id
       or c_visit.branch_id is distinct from n_visit.branch_id
       or (c_visit.created_at at time zone 'Asia/Jakarta')::date <> (n_visit.created_at at time zone 'Asia/Jakarta')::date then
      raise exception 'KODE_KAMPANYE: Nota rombongan tidak cocok dengan nota pembawa kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.campaign_code is null then
    if public.voucher_wajib_lewat_kampanye(new.voucher_code) then
      raise exception 'KODE_KAMPANYE: Voucher ini hanya bisa dipakai lewat kode kampanye' using errcode = '23514';
    end if;
    return new;
  end if;

  -- Row lock serializes every checkout of this code until its transaction ends.
  select * into k from public.campaign_codes cc where cc.code = new.campaign_code for update;
  if not found then
    raise exception 'KODE_KAMPANYE: Kode % tidak ditemukan', new.campaign_code using errcode = 'P0001';
  end if;
  if not k.is_active then
    raise exception 'KODE_KAMPANYE: Kode % sedang dinonaktifkan', k.code using errcode = 'P0001';
  end if;
  if k.voucher_id is not null then
    select v.code into v_voucher from public.vouchers v where v.id = k.voucher_id;
    if new.voucher_code is distinct from v_voucher then
      raise exception 'KODE_KAMPANYE: Kode % harus memakai voucher %', k.code, v_voucher using errcode = '23514';
    end if;
  elsif new.voucher_code is not null then
    raise exception 'KODE_KAMPANYE: Kode promo % tidak bisa digabung dengan voucher', k.code using errcode = '23514';
  end if;
  if k.max_uses is not null then
    v_used := public.campaign_code_used(k.code);
    if v_used >= k.max_uses then
      raise exception 'KODE_KAMPANYE: Kode % sudah mencapai batas pemakaian (% kali)', k.code, k.max_uses
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.guard_campaign_code_use() from public, anon, authenticated, service_role;

-- The marker is guarded on update as well (sales keep the original trigger: no such column).
drop trigger if exists c05_invoice_campaign_code on public.invoices;
create trigger c05_invoice_campaign_code before insert or update of campaign_code, voucher_code, campaign_carrier_id on public.invoices
  for each row execute function public.guard_campaign_code_use();

-- Clinic posting stores the marker inside its own atomic invoice insert.
do $patch$
declare
  signature regprocedure := 'public.clinic_post_invoice(uuid,text,jsonb,jsonb)'::regprocedure;
  definition text := pg_get_functiondef(signature);
  cols_old text := 'service_pricing_version, campaign_code';
  vals_old text := E'nullif(p_invoice->>''campaign_code'','''')';
begin
  if position('campaign_carrier_id' in definition) > 0 then
    return;                                        -- already applied (idempotent re-run)
  end if;
  if (length(definition) - length(replace(definition, cols_old, ''))) / length(cols_old) <> 1
     or (length(definition) - length(replace(definition, vals_old, ''))) / length(vals_old) <> 1 then
    raise exception 'C05_CLINIC_POST_DRIFT: clinic_post_invoice changed; review before release';
  end if;
  definition := replace(definition, cols_old, cols_old || ', campaign_carrier_id');
  definition := replace(definition, vals_old, vals_old || E', nullif(p_invoice->>''campaign_carrier_id'','''')::uuid');
  execute definition;
end
$patch$;

-- M04/M01 keputusan pemilik 29 Okt: nilai persediaan awal dibulatkan ke rupiah penuh PER BARIS
-- saat batch disiapkan; selisih total terhadap nilai sumber dicatat di batch.
-- Hanya fungsi persiapan (batch yang belum diposting) yang berubah. Preview/posting,
-- kunci posting sekali (20261021123000), dan semua batch yang sudah tersimpan/diposting tidak disentuh.
-- Jurnal tetap Dr 1301 / Cr ekuitas sebesar nilai yang diposting (seimbang sendiri), jadi tidak
-- perlu akun selisih pembulatan; selisih terhadap sumber tersimpan di summary.valuation batch dan
-- ikut tersalin ke bukti posting (accurate_inventory_accounting.preview.evidence.summary).
create function pg_temp.patch_line_rounding(p_function regprocedure,p_old text,p_new text)
returns void language plpgsql as $patch$
declare definition text:=pg_get_functiondef(p_function);
begin
 if (length(definition)-length(replace(definition,p_old,'')))/length(p_old)<>1 then
  raise exception 'Line rounding anchor mismatch: % / %',p_function,left(p_old,100);
 end if;
 execute replace(definition,p_old,p_new);
end;
$patch$;

select pg_temp.patch_line_rounding('public.prepare_accurate_initial_stock(text,text,uuid,uuid,date,jsonb,text)'::regprocedure,
$old$ n int:=0; skipped int:=0; rejected int:=0; total_qty numeric:=0; has_history int:=0;$old$,
$new$ n int:=0; skipped int:=0; rejected int:=0; total_qty numeric:=0; has_history int:=0;
 line_value numeric; hi_qty numeric; source_lines int:=0; split_lines int:=0;$new$);

select pg_temp.patch_line_rounding('public.prepare_accurate_initial_stock(text,text,uuid,uuid,date,jsonb,text)'::regprocedure,
$old$ or p_policy not in ('STRICT','HALF_UP_BATCH_V1') or p_policy is null$old$,
$new$ or p_policy not in ('STRICT','HALF_UP_BATCH_V1','ROUND_LINE_RUPIAH_V1') or p_policy is null$new$);

select pg_temp.patch_line_rounding('public.prepare_accurate_initial_stock(text,text,uuid,uuid,date,jsonb,text)'::regprocedure,
$old$   payload:=payload||jsonb_build_object('base_qty',row_qty::text,'base_unit_cost',rate::text,
    'source_value',row_source::text,'original_base_unit_cost',rate::text,'normalization_policy',p_policy);
   source_value:=source_value+row_source;posted_value:=posted_value+row_qty*rate;total_qty:=total_qty+row_qty;n:=n+1;$old$,
$new$   if p_policy='ROUND_LINE_RUPIAH_V1' then
    -- Nilai baris = round(qty*HPP sumber) HALF_UP ke rupiah penuh; HPP dasar diturunkan dari nilai itu.
    line_value:=round(row_source,0);
    payload:=payload||jsonb_build_object('source_value',row_source::text,'line_value',line_value::text,
     'line_rounding',(line_value-row_source)::text,'line_qty',row_qty::text,
     'original_base_unit_cost',rate::text,'normalization_policy',p_policy);
    rate:=trunc(line_value::numeric(200,100)/row_qty,60);
    if row_qty*rate<>line_value then
     -- Nilai/qty tanpa desimal berhingga (mis. Rp10/3): baris dibawa tepat oleh dua layer lot yang sama
     -- dengan HPP sen r+0,01 dan r. Keduanya memakai source_row yang sama dan ditandai line_part.
     rate:=round(floor((line_value*100)::numeric(200,100)/row_qty)/100,2);
     hi_qty:=line_value*100-row_qty*rate*100;
     if hi_qty<=0 or hi_qty>=row_qty or hi_qty*(rate+0.01)+(row_qty-hi_qty)*rate<>line_value then
      raise exception 'Nilai baris % tidak dapat dibawa tepat dalam rupiah penuh. Perbaiki nilai sumber.',x->>'source_row' using errcode='22023';end if;
     prepared:=prepared||jsonb_build_array(x||jsonb_build_object('payload',payload||jsonb_build_object(
      'base_qty',hi_qty::text,'base_unit_cost',(rate+0.01)::text,'line_part',1)));
     n:=n+1;split_lines:=split_lines+1;
     payload:=payload||jsonb_build_object('base_qty',(row_qty-hi_qty)::text,'base_unit_cost',rate::text,'line_part',2);
    else
     payload:=payload||jsonb_build_object('base_qty',row_qty::text,'base_unit_cost',rate::text);
    end if;
    source_value:=source_value+row_source;posted_value:=posted_value+line_value;total_qty:=total_qty+row_qty;n:=n+1;
   else
   payload:=payload||jsonb_build_object('base_qty',row_qty::text,'base_unit_cost',rate::text,
    'source_value',row_source::text,'original_base_unit_cost',rate::text,'normalization_policy',p_policy);
   source_value:=source_value+row_source;posted_value:=posted_value+row_qty*rate;total_qty:=total_qty+row_qty;n:=n+1;
   end if;
   source_lines:=source_lines+1;$new$);

select pg_temp.patch_line_rounding('public.prepare_accurate_initial_stock(text,text,uuid,uuid,date,jsonb,text)'::regprocedure,
$old$ 'control','computed_from_source_not_authoritative')))$old$,
$new$ 'control','computed_from_source_not_authoritative',
 'rounding_difference',(posted_value-source_value)::text,'source_lines',source_lines,
 'line_rounding',case when p_policy='ROUND_LINE_RUPIAH_V1' then jsonb_build_object('unit','1','mode','HALF_UP','split_lines',split_lines) end)))$new$);

